def _marker_underline(stroke: float = 4.0, color: str = "var(--seafoam-deep)") -> str:
    """Hand-drawn wavy SVG underline for one hero heading word. Stretches to
    fill its parent's width (`preserveAspectRatio="none"`, a fixed viewBox).
    Rendered as a normal block-flow sibling of the word (see
    `_underline_last_word`) rather than absolutely positioned, so its height
    is always counted as real, in-flow space — no reliance on a parent's
    padding/line-height/inline-block quirks to avoid overlapping whatever
    follows. Max one per page."""
    h = max(10, round(stroke * 3.5))
    mid = h - 6
    d = f"M2,{mid} Q15,{max(2, mid - 6)} 30,{mid + 2} T60,{mid} T98,{mid + 3}"
    return (
        f'<svg width="100%" height="{h}" viewBox="0 0 100 {h}" preserveAspectRatio="none" '
        f'aria-hidden="true" style="display:block;margin-top:4px;">'
        f'<path d="{d}" fill="none" stroke="{color}" stroke-width="{stroke}" '
        f'stroke-linecap="round" vector-effect="non-scaling-stroke"/></svg>'
    )


def _underline_last_word(text: str, stroke: float = 4.0, color: str = "var(--seafoam-deep)") -> str:
    """Wrap the last word of `text` (raw, unescaped) in a marker-underline —
    the safe way to accent one word of arbitrary/admin-edited heading copy,
    since it doesn't require knowing the word in advance. The word and its
    underline are stacked in a single-column `display:inline-grid` (not
    `inline-flex`) — a grid's height is always the sum of its rows the same
    way a flex column's is (fixing the old padding-bottom-on-inline-block
    bug where reserved space could come up short), but a flex column with an
    indefinite (shrink-to-fit) cross size can't resolve the SVG's
    `width:100%` against its sibling's text width — the browser falls back
    to the SVG's own intrinsic aspect-ratio size instead, so the underline
    renders far short of the word (only visible with real font metrics
    loaded, not in a computed-style check). Grid does a two-pass track-size
    resolution built for exactly this: the column sizes to the widest
    non-percentage item (the word) first, then percentage-sized items
    stretch to fill it."""
    head, sep, last = text.rstrip().rpartition(" ")
    underlined = (f'<span style="display:inline-grid;justify-items:stretch;">'
                  f'<span>{_esc(last)}</span>{_marker_underline(stroke, color)}</span>')
    return f"{_esc(head)} {underlined}" if sep else underlined


def _underline_phrase(text: str, phrase: str, stroke: float = 4.0, color: str = "var(--seafoam-deep)") -> str:
    """Wrap the first case-insensitive occurrence of `phrase` (raw,
    unescaped) inside `text` in the same marker-underline `_underline_last_word`
    draws, but mid-sentence rather than at the end — the homepage hero
    heading's design specifically accents "strategic partner", not whatever
    word happens to end the (admin-editable) headline. Falls back to
    `_underline_last_word` when `phrase` isn't found in `text` at all (e.g.
    an admin rewrites the headline without that phrase) so there's always
    still an accent rather than none."""
    lower_text, lower_phrase = text.lower(), phrase.lower()
    idx = lower_text.find(lower_phrase)
    if idx == -1:
        return _underline_last_word(text, stroke, color)
    before, match, after = text[:idx], text[idx:idx + len(phrase)], text[idx + len(phrase):]
    underlined = (f'<span style="display:inline-grid;justify-items:stretch;">'
                  f'<span>{_esc(match)}</span>{_marker_underline(stroke, color)}</span>')
    return f"{_esc(before)}{underlined}{_esc(after)}"


def _card_icon(index: int, svg_path: str, size: int = 34) -> str:
    """2px-stroke line-icon badge for a card-row grid (2-up, 3-up, or 4-up).
    Cycles seafoam-wash -> navy-wash -> coral-wash by `index`, the fixed
    order reused for every card-row grid sitewide (homepage, CFO Toolbox,
    Library, Thought Leadership). `svg_path` is the inner SVG markup
    (path/rect/etc.) for a 24x24 viewBox icon."""
    bg, stroke = _CARD_ICON_STYLES[index % 3]
    inner = size - 16
    return (
        f'<div style="width:{size}px;height:{size}px;border-radius:8px;background:{bg};'
        f'margin-bottom:14px;display:flex;align-items:center;justify-content:center;">'
        f'<svg viewBox="0 0 24 24" width="{inner}" height="{inner}" fill="none" stroke="{stroke}" '
        f'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{svg_path}</svg></div>'
    )


