@app.post("/reset-password")
async def reset_password_submit(request: Request):
    form = await request.form()
    token = form.get("token") or ""
    password = form.get("password") or ""
    lib = _lib()
    try:
        req = lib.get_password_reset_by_token_hash(hashlib.sha256(token.encode("utf-8")).hexdigest()) if token else None
        if not req:
            return RedirectResponse(f"/reset-password?token={quote(token)}", status_code=303)
        if len(password) < 8:
            return RedirectResponse(f"/reset-password?token={quote(token)}&error=1", status_code=303)
        lib.set_user_password(req["user_id"], password)
        # The account holder just chose their own password — clear the
        # nudge (mirrors admin_users_password setting it True for the
        # opposite case: an admin choosing it for them).
        lib.set_password_change_recommended(req["user_id"], False)
        lib.resolve_password_resets_for_user(req["user_id"])
    finally:
        lib.close()
    return RedirectResponse("/login?reset=1", status_code=303)


@app.post("/login")
async def login_submit(request: Request):
    form = await request.form()
    username = (form.get("username") or "").strip()
    password = form.get("password") or ""
    safe_next = _safe_next(form.get("next"))

    role = username_for_cookie = None
    if username:
        lib = _lib()
        try:
            user = lib.authenticate(username, password)
        finally:
            lib.close()
        if user:
            role, username_for_cookie = user["role"], user["username"]
        elif (AUTH_PASSWORD and username.lower() == ADMIN_USERNAME
              and hmac.compare_digest(password, AUTH_PASSWORD)):
            # break-glass: the host password, used with the reserved admin username
            role, username_for_cookie = "admin", ADMIN_USERNAME

    if role:
        # An explicit, validated `next` wins regardless of role. Otherwise,
        # default by role: admins land in the back office, everyone else on
        # the public homepage (never /library — that's not every user's home).
        dest = safe_next or ("/admin" if role == "admin" else "/")
        resp = RedirectResponse(dest, status_code=303)
        secure = (request.url.scheme == "https"
                  or request.headers.get("x-forwarded-proto") == "https")
        resp.set_cookie(COOKIE_NAME, _make_session(role, username_for_cookie),
                        max_age=SESSION_TTL, httponly=True, samesite="lax",
                        secure=secure, path="/")
        return resp
    next_qs = f"&next={quote(safe_next, safe='')}" if safe_next else ""
    return RedirectResponse(f"/login?error=1{next_qs}", status_code=303)


@app.get("/logout")
def logout():
    resp = RedirectResponse("/", status_code=303)
    resp.delete_cookie(COOKIE_NAME, path="/")
    return resp


