# The one Speaking & Events entry with photos (Abacum AI Summit). Excluded
# from the thought_leadership DB table/admin CRUD (Phase 1 — photos are a
# single-use field, not worth the upload/JSON handling for one entry; see
# CLAUDE.md), but kept rendering in its column so it doesn't silently
# disappear. Hardcoded here rather than imported from
# webapp/thought_leadership_data.py, which stays in the repo unused as a
# rollback reference. `photos`/`photo_caption` aren't read by any current
# rendering path (col_preview_item never touches them) — kept for parity
# with the pre-migration data in case a future "Show all" listing page uses
# them.
_TL_PHOTO_ENTRY = {
    "type": "speaking",
    "title": "Abacum AI Summit—Recording",
    "url": "https://www.youtube.com/watch?v=MDBz0OpR1II",
    "venue": "Abacum",
    "date_label": "Apr 2026",
    "sort_key": "2026-04",
    "description": ("A panel on what AI adoption changes inside a finance team once the pilot phase ends, "
                     "recorded live at Abacum's invite-only summit in New York."),
    "needs_synopsis": False,
    "display_order": 0,
    "photos": [
        {"src": "/static/speaking-close.jpg",
         "alt": "Brian Weisberg speaking at the Abacum AI Summit, April 2026"},
        {"src": "/static/speaking-wide.jpg",
         "alt": "Panel discussion at the Abacum AI Summit, April 2026"},
    ],
    "photo_caption": "Abacum AI Summit · New York · April 2026",
}


@app.get("/thought-leadership", response_class=HTMLResponse)
def thought_leadership(request: Request):
    def ordered_items(items: list[dict]) -> list[dict]:
        # Undated items (sort_key == "") float to the top of their section — a
        # standing "full feed" link or similar; everything else sorts newest
        # first. display_order is the tiebreaker within each group (two sorts,
        # relying on Python's stable sort — the tiebreak pass runs first).
        dated = [it for it in items if it["sort_key"]]
        dated.sort(key=lambda it: it["display_order"])
        dated.sort(key=lambda it: it["sort_key"], reverse=True)
        undated = [it for it in items if not it["sort_key"]]
        undated.sort(key=lambda it: it["display_order"])
        return undated + dated

    def col_preview_item(it: dict, item_id: str, hidden: bool = False) -> str:
        meta_bits = [b for b in (it["venue"], it["date_label"]) if b]
        meta_html = (f'<div class="tl-col-item-meta">{" &middot; ".join(_esc(b) for b in meta_bits)}</div>'
                     if meta_bits else "")
        title_html = (f'<a href="{_esc(it["url"])}" target="_blank" rel="noopener" class="tl-col-item-title">{_esc(it["title"])}</a>'
                      if it["url"] else f'<div class="tl-col-item-title">{_esc(it["title"])}</div>')
        cls = "tl-col-item tl-col-item-extra" if hidden else "tl-col-item"
        # The description is never shown by default (title/venue/date only,
        # matching the page's existing look) — a small chevron toggle reveals
        # it inline, independent per entry. Suppressed entirely when there's
        # nothing to reveal: no description, or needs_synopsis (a deliberate
        # placeholder, not real content) — no point inviting a click that
        # does nothing. A full-row click was considered and rejected: most
        # entries' title is itself a link out to the piece, so a row-level
        # handler would fight that link for the click.
        desc_id = f"tl-desc-{item_id}"
        toggle_html = ""
        if it["description"] and not it.get("needs_synopsis"):
            toggle_html = (
                f'<button type="button" class="tl-col-item-toggle" aria-expanded="false" aria-controls="{desc_id}" '
                f'onclick="toggleTLDesc(this,\'{desc_id}\')">'
                '<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" '
                'stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>'
                'More</button>'
                f'<div class="tl-col-item-desc" id="{desc_id}" hidden>{_esc(it["description"])}</div>'
            )
        return f'<div class="{cls}">{title_html}{meta_html}{toggle_html}</div>'

    _TL_COL_CAP = 6

    def column(index: int, icon_svg: str, title: str, items: list[dict]) -> str:
        # Press collapses to nothing (not an empty card) when there's nothing to
        # show — cap each column at ~6 items with a "Show all N" toggle that
        # expands the rest in place, so the overview stays scannable without
        # depending on a separate full list elsewhere on the page.
        if not items:
            return ""
        ordered = ordered_items(items)
        preview = ordered[:_TL_COL_CAP]
        extra = ordered[_TL_COL_CAP:]
        rows = "".join(col_preview_item(it, f"{index}-{n}") for n, it in enumerate(preview))
        rows += "".join(col_preview_item(it, f"{index}-{n + len(preview)}", hidden=True) for n, it in enumerate(extra))
        col_id = f"tl-col-{index}"
        more = (f'<a href="#" class="tl-col-more" onclick="toggleTLCol(event,\'{col_id}\')" '
                f'data-more-label="Show all {len(ordered)} &rarr;">Show all {len(ordered)} &rarr;</a>'
                if extra else "")
        return (
            f'<div class="tl-col" id="{col_id}">'
            f'<div class="tl-col-head">{_card_icon(index, icon_svg)}<div class="tl-col-title">{_esc(title)}</div></div>'
            f'{rows}{more}</div>'
        )

    # Featured: every live original_content piece, one consistent card
    # treatment — same shared _oc_featured_cards_html/_tl_fcard/_TL_SHARED_CSS
    # markup as the homepage's own flagship row (Original Content Phase 1),
    # so the two surfaces can't drift apart. The only per-card variation
    # here is the small category tag colour — no full-colour floods, which
    # is what made the old top read as busy.
    lib = _lib()
    try:
        sections = [
            ("Writing", "writing", lib.list_thought_leadership(type="writing")),
            ("Speaking & Events", "speaking", lib.list_thought_leadership(type="speaking") + [_TL_PHOTO_ENTRY]),
            ("Podcasts", "podcast", lib.list_thought_leadership(type="podcast")),
            ("Press", "press", lib.list_thought_leadership(type="press")),
        ]
        original_content_live = lib.list_original_content(status="live")
    finally:
        lib.close()

    body = (
        '<div class="page page-full">'
        '<style>'
        + _TL_SHARED_CSS + _TL_COLUMN_CSS +
        '</style>'
        '<h1>Thought leadership</h1>'
        '<p style="max-width:680px;color:var(--muted);margin:4px 0 24px;">Writing, talks, podcasts, and press&mdash;from a tech CFO working in the thick of the business.</p>'
        + _oc_featured_cards_html(original_content_live)
    )

    columns_html = "".join(
        column(i, _TL_COLUMN_ICONS[i % len(_TL_COLUMN_ICONS)], section_title, items)
        for i, (section_title, _type, items) in enumerate(sections)
    )
    body += f'<div class="tl-cols">{columns_html}</div>'
    body += """<script>
function toggleTLCol(e, colId) {
  e.preventDefault();
  var col = document.getElementById(colId);
  var btn = col.querySelector('.tl-col-more');
  var expanded = btn.dataset.expanded === '1';
  col.querySelectorAll('.tl-col-item-extra').forEach(function(el) {
    el.style.display = expanded ? 'none' : 'block';
  });
  btn.innerHTML = expanded ? btn.dataset.moreLabel : 'Show less';
  btn.dataset.expanded = expanded ? '0' : '1';
}
function toggleTLDesc(btn, descId) {
  var desc = document.getElementById(descId);
  var expanded = btn.getAttribute('aria-expanded') === 'true';
  desc.hidden = expanded;
  btn.setAttribute('aria-expanded', expanded ? 'false' : 'true');
  btn.lastChild.textContent = expanded ? 'More' : 'Less';
}
</script>"""
    body += "</div>"
    return HTMLResponse(_page("Thought leadership—Brian Weisberg", "Thought leadership", body, role=_role(request)))


@app.get("/growth-engine-ratio")
def growth_engine_ratio_redirect(request: Request):
    target = "/thought-leadership/growth-engine-ratio"
    if request.url.query:
        target += "?" + request.url.query
    return RedirectResponse(target, status_code=301)


# Original Content Phase 4c — the standalone Growth Engine Ratio
# calculator. Split off from the retired growth_engine_ratio() bespoke
# route: the article itself is now an ordinary original_content row served
# through GET /thought-leadership/{slug} (see
# scripts/migrate_growth_engine_ratio_content.py), but the calculator is
# genuinely interactive (live inputs, on-demand JS computation, two
# dynamically-generated SVG charts) — not markdown-representable content —
# so it stays a hand-built Python route, same as before, just at its own
# URL and with the article's prose/table/CTA content removed.
#
# Extraction discipline: the calculator's own markup, CSS, and ~380 lines
# of JS below are copied byte-for-byte from the retired route — no logic,
# input, or chart-generation change. Only new content on this page is the
# back-link, the eyebrow/H1, and the intro blurb immediately below —
# flagged for Brian's review per the process note in this PR (new copy, not
# ported copy).
