# -- Feature Taxonomy: Review Queue (rules doc §9) ---------------------------
# Visual shape borrows from Archive Queue (Phase 0's admin-pattern
# investigation): a list of pending items with approve/deny actions, grouped
# so the source (admin/scan/public) is always visible. "Edit-then-approve"
# is the same approve action with the form fields pre-filled from the
# proposal but editable — no separate route.

# Feature Taxonomy scan tool, Phase 3 complement (2026-08) — a source-
# agnostic near-duplicate nudge on the review queue itself, built alongside
# Phase 3's own clustering/judgment pass rather than as a separate phase.
# The scan's own §7 merge test runs at drafting time, biased conservative
# (split when uncertain — see linklib/feature_scan.py's Phase 3 section);
# this catches whatever that conservative bias deliberately leaves behind
# (two near-duplicate names both queued separately), AND anything else that
# lands two similarly-named pending proposals in the same category — a
# second scan run, an admin's own manual entry, a public suggestion. Pure
# Python (difflib), no LLM call, no dependency on the scan having run at
# all.
_NEAR_DUPLICATE_NAME_THRESHOLD = 0.6


def _find_near_duplicate_queue_items(pending: list[dict]) -> dict[int, list[dict]]:
    """item_id -> [{"id","name"}, ...] of OTHER pending items in the same
    category whose feature name looks similar enough to be worth a human
    double-checking before approving either. Only compares items proposing
    a NEW feature (is_new_feature) — an existing-feature link proposal has
    no name of its own to compare. difflib.SequenceMatcher on lowercased
    names; the threshold is a starting point, not tuned against real data
    yet — revisit once this has run against a real multi-tool category."""
    by_category: dict[int, list[dict]] = {}
    for item in pending:
        feature = (item.get("payload") or {}).get("feature") or {}
        name = (feature.get("name") or "").strip()
        if not name:
            continue
        by_category.setdefault(item.get("category_id"), []).append(
            {"id": item["id"], "name": name}
        )

    result: dict[int, list[dict]] = {}
    for items in by_category.values():
        for i, a in enumerate(items):
            matches = []
            for j, b in enumerate(items):
                if i == j:
                    continue
                ratio = difflib.SequenceMatcher(
                    None, a["name"].lower(), b["name"].lower()
                ).ratio()
                if ratio >= _NEAR_DUPLICATE_NAME_THRESHOLD:
                    matches.append(b)
            if matches:
                result[a["id"]] = matches
    return result


def _articulation_tool_coverage(articulation: str, tool_names: list[str]) -> tuple[list[str], list[str]]:
    """Splits `tool_names` into (mentioned, unmentioned) by a case-insensitive
    substring check against `articulation`'s text — a coarse heuristic (no
    NLP), deliberately just good enough to prompt a human reviewer to look,
    never used to auto-deny or block anything. Built for the pattern a
    Neobanking review caught by hand (2026-08): a queue item's merge
    reasoning named only 2 of its 5 linked tools, with no explanation for
    the other 3 — which turned out to be a genuine mismerge (those 3 were
    already correctly linked to a separately-approved feature), not a real
    5-vendor feature. Surfacing "this note doesn't cover all its own
    links" as a visible flag lets a reviewer catch that before approving,
    rather than only after noticing by hand."""
    text = (articulation or "").lower()
    mentioned, unmentioned = [], []
    for name in tool_names:
        (mentioned if name.lower() in text else unmentioned).append(name)
    return mentioned, unmentioned


def _feature_review_queue_item_card(item: dict, categories: dict[int, dict], tools_by_id: dict[int, dict],
                                     near_duplicates: list[dict] | None = None) -> str:
    """The approve form IS the edit form — every proposed value is a real
    editable input pre-filled from the payload, so clicking Approve with no
    changes is a verbatim approval and changing a value first is
    "edit-then-approve" (rules doc §9), both through the one action/route.
    Deny is a separate small form alongside it."""
    payload = item["payload"]
    category = categories.get(item["category_id"])
    category_name = category["name"] if category else "(unknown category)"

    # A "flag" proposal (public suggestion channel, §9) has no proposed
    # change to apply — it's a report, not a draft — so it gets its own
    # render branch entirely: no edit-as-approve form (there's nothing in
    # payload["links"] to apply, and calling approve_feature_review_queue_item
    # on it would silently no-op against tool_feature_links, which would
    # read as "approved" when nothing actually happened). Just the flagged
    # tool/feature, the visitor's note, and a Dismiss action.
    if item.get("proposal_type") == "flag":
        source_badge_bg = {"admin": "var(--navy-wash)", "scan": "var(--seafoam-wash)", "public": "#fef3c7"}.get(item["source"], "var(--bg)")
        source_badge_fg = {"admin": "var(--navy)", "scan": "var(--seafoam-deep)", "public": "#92400e"}.get(item["source"], "var(--ink)")
        tool = tools_by_id.get(item.get("tool_id"))
        tool_label = tool["name"] if tool else f"(tool id={item.get('tool_id')})"
        feature_id = payload.get("feature_id")
        return f"""<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-bottom:16px;">
  <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;">
    <span style="font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;background:{source_badge_bg};color:{source_badge_fg};border-radius:5px;padding:2px 9px;">{_esc(item['source'])}</span>
    <span style="font-size:13px;color:var(--muted);">Flag/question &middot; {_esc(category_name)}</span>
  </div>
  <p style="margin:0 0 6px;font-size:14px;">{_esc(tool_label)} &mdash; feature id={feature_id}</p>
  {f'<p style="font-size:13.5px;line-height:1.6;color:var(--ink);background:var(--bg);border-radius:8px;padding:10px 12px;margin:10px 0 0;">{_esc(item["articulation"])}</p>' if item.get("articulation") else '<p style="font-size:13.5px;color:var(--muted);margin:10px 0 0;">No note left&mdash;just flagged for review.</p>'}
  {f'<p style="font-size:13px;color:var(--muted);margin:8px 0 0;">From {_esc(item["submitter_name"])} ({_esc(item["submitter_email"])})</p>' if item.get("submitter_name") else ''}
  <form method="post" action="/admin/tools/software/feature-review-queue/{item['id']}/deny" style="margin:14px 0 0;display:flex;gap:6px;align-items:center;">
    <input type="text" name="resolution_note" placeholder="Note (optional, shown as resolved)" maxlength="500"
      style="flex:1;min-width:180px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:13px;background:#fff;">
    <button type="submit" class="btn btn-ghost" style="font-size:13px;padding:7px 16px;">Dismiss</button>
  </form>
</div>"""

    feature = payload.get("feature") or {}
    is_new_feature = bool(feature.get("name"))
    feature_name = feature.get("name", "")

    def _in(name, value, extra="", width="auto"):
        return (f'<input type="text" name="{name}" value="{_esc(str(value))}" maxlength="500" {extra}'
                f'style="width:{width};padding:5px 8px;border:1px solid var(--line);border-radius:6px;font:inherit;font-size:13px;background:#fff;">')

    link_rows = ""
    for i, link in enumerate(payload.get("links", [])):
        t = tools_by_id.get(link.get("tool_id"))
        tool_label = t["name"] if t else f"(tool id={link.get('tool_id')})"
        avail = link.get("availability", "native")
        avail_select = (
            f'<select name="link_{i}_availability" style="padding:5px 6px;border:1px solid var(--line);border-radius:6px;font:inherit;font-size:13px;background:#fff;">'
            f'<option value="native"{" selected" if avail == "native" else ""}>native</option>'
            f'<option value="add_on"{" selected" if avail == "add_on" else ""}>add_on</option></select>'
        )
        ai_checked = "checked" if link.get("ai_enabled") else ""
        link_rows += f"""<tr style="border-top:1px solid var(--line);">
  <td style="padding:6px 10px;font-size:13px;">{_esc(tool_label)}<input type="hidden" name="link_{i}_tool_id" value="{link.get('tool_id')}">
    <input type="hidden" name="link_{i}_note" value="{_esc(link.get('note', ''))}">
    <input type="hidden" name="link_{i}_source_url" value="{_esc(link.get('source_url', ''))}"></td>
  <td style="padding:6px 10px;">{avail_select}</td>
  <td style="padding:6px 10px;text-align:center;"><input type="checkbox" name="link_{i}_ai_enabled" value="1" {ai_checked}></td>
  <td style="padding:6px 10px;">{_in(f"link_{i}_verified_as_of", link.get("verified_as_of", ""), width="110px")}</td>
</tr>"""
    n_links = len(payload.get("links", []))

    source_badge_bg = {"admin": "var(--navy-wash)", "scan": "var(--seafoam-wash)", "public": "#fef3c7"}.get(item["source"], "var(--bg)")
    source_badge_fg = {"admin": "var(--navy)", "scan": "var(--seafoam-deep)", "public": "#92400e"}.get(item["source"], "var(--ink)")

    feature_field_html = (
        f'<div style="margin:0 0 10px;">'
        f'<label style="display:block;font-size:12px;font-weight:500;color:var(--navy);margin-bottom:4px;">Name</label>'
        f'{_in("feature_name", feature_name, width="320px")}'
        f'</div>'
        f'<div>'
        f'<label style="display:block;font-size:12px;font-weight:500;color:var(--navy);margin-bottom:4px;">Pointer note '
        f'<span style="font-weight:400;color:var(--muted);">(optional)</span></label>'
        f'{_in("pointer_note", feature.get("pointer_note", ""), width="320px")}'
        f'</div>'
        if is_new_feature else
        f'<p style="margin:0 0 6px;font-size:14px;">Existing feature id={payload.get("feature_id")}'
        f'<input type="hidden" name="feature_id" value="{payload.get("feature_id")}"></p>'
    )

    near_dup_html = ""
    if near_duplicates:
        names = ", ".join(f'"{_esc(d["name"])}" (#{d["id"]})' for d in near_duplicates)
        near_dup_html = (
            f'<p style="font-size:12.5px;color:#92400e;background:#fef3c7;border-radius:8px;'
            f'padding:6px 10px;margin:0 0 10px;">Possible near-duplicate of {names} — worth '
            f'checking these describe genuinely different jobs (FEATURE_TAXONOMY.md &sect;7) '
            f'before approving both.</p>'
        )

    coverage_html = ""
    if item.get("articulation") and len(payload.get("links", [])) >= 2:
        link_tool_names = [
            tools_by_id[l["tool_id"]]["name"] for l in payload.get("links", []) if l.get("tool_id") in tools_by_id
        ]
        mentioned, unmentioned = _articulation_tool_coverage(item["articulation"], link_tool_names)
        if mentioned and unmentioned:
            coverage_html = (
                f'<p style="font-size:12.5px;color:#92400e;background:#fef3c7;border-radius:8px;'
                f'padding:6px 10px;margin:10px 0 0;">Articulation names only {len(mentioned)} of '
                f'{len(mentioned) + len(unmentioned)} linked tools ({_esc(", ".join(mentioned))}) — '
                f'{_esc(", ".join(unmentioned))} '
                f'{"aren&rsquo;t" if len(unmentioned) > 1 else "isn&rsquo;t"} mentioned. Worth checking '
                f'whether this is a real feature for every linked tool, or a mismerge (a tool that '
                f'already belongs to a different, separately-approved feature) before approving.</p>'
            )

    return f"""<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-bottom:16px;">
  <form method="post" action="/admin/tools/software/feature-review-queue/{item['id']}/approve">
  <input type="hidden" name="n_links" value="{n_links}">
  <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;">
    <span style="font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;background:{source_badge_bg};color:{source_badge_fg};border-radius:5px;padding:2px 9px;">{_esc(item['source'])}</span>
    <span style="font-size:13px;color:var(--muted);">{_esc(item.get('proposal_type', ''))} &middot; {_esc(category_name)}</span>
  </div>
  {near_dup_html}
  <label style="display:block;font-size:12px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px;">Feature{' (new)' if is_new_feature else ''}</label>
  {feature_field_html}
  {f'<div style="overflow-x:auto;margin:12px 0;"><table style="width:100%;border-collapse:collapse;"><thead><tr style="background:var(--bg);"><th style="padding:6px 10px;text-align:left;font-size:11px;color:var(--muted);text-transform:uppercase;">Tool</th><th style="padding:6px 10px;text-align:left;font-size:11px;color:var(--muted);text-transform:uppercase;">Availability</th><th style="padding:6px 10px;text-align:left;font-size:11px;color:var(--muted);text-transform:uppercase;">AI</th><th style="padding:6px 10px;text-align:left;font-size:11px;color:var(--muted);text-transform:uppercase;">Verified as of</th></tr></thead><tbody>{link_rows}</tbody></table></div>' if link_rows else ''}
  {f'<p style="font-size:13.5px;line-height:1.6;color:var(--ink);background:var(--bg);border-radius:8px;padding:10px 12px;margin:10px 0 0;">{_esc(item["articulation"])}</p>' if item.get("articulation") else ''}
  {coverage_html}
  {f'<p style="font-size:13px;color:var(--muted);margin:8px 0 0;">From {_esc(item["submitter_name"])} ({_esc(item["submitter_email"])})</p>' if item.get("submitter_name") else ''}
  <div style="margin-top:14px;">
    <button type="submit" class="btn" style="font-size:13px;padding:7px 16px;">Approve</button>
  </div>
  </form>
  <form method="post" action="/admin/tools/software/feature-review-queue/{item['id']}/deny" style="margin:10px 0 0;display:flex;gap:6px;align-items:center;"
        onsubmit="return confirm('Deny this proposal?');">
    <input type="text" name="resolution_note" placeholder="Reason (optional, shown if denied)" maxlength="500"
      style="flex:1;min-width:180px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:13px;background:#fff;">
    <button type="submit" class="btn btn-ghost" style="font-size:13px;padding:7px 16px;color:#b91c1c;border-color:#fca5a5;">Deny</button>
  </form>
</div>"""


@app.get("/admin/tools/software/feature-review-queue", response_class=HTMLResponse)
def admin_feature_review_queue(request: Request, msg: str = ""):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        pending = lib.list_feature_review_queue(status="pending")
        categories = {c["id"]: c for c in lib.list_tool_categories()}
        tools_by_id = {t["id"]: t for t in lib.list_tools(approved_only=False)}
    finally:
        lib.close()

    banner = (f'<p style="background:#d1fae5;color:#065f46;border-radius:10px;padding:10px 16px;'
              f'font-size:14px;margin:-6px 0 16px;">{_esc(msg)}</p>' if msg else '')

    by_source: dict[str, list[dict]] = {"admin": [], "scan": [], "public": []}
    for item in pending:
        by_source.setdefault(item["source"], []).append(item)

    near_duplicates = _find_near_duplicate_queue_items(pending)

    sections = ""
    source_labels = {"admin": "Admin edits", "scan": "AI scan proposals", "public": "Public suggestions"}
    for source in ("public", "scan", "admin"):
        items = by_source.get(source, [])
        if not items:
            continue
        cards = "".join(
            _feature_review_queue_item_card(i, categories, tools_by_id, near_duplicates.get(i["id"]))
            for i in items
        )
        sections += f'<h2 style="font-size:16px;margin:24px 0 10px;">{source_labels[source]} ({len(items)})</h2>{cards}'

    if not sections:
        sections = '<p style="color:var(--muted);padding:24px;text-align:center;background:var(--surface);border:1px solid var(--line);border-radius:14px;">Nothing pending review.</p>'

    body = f"""<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<h1>Feature review queue</h1>
<p style="color:var(--muted);margin:-6px 0 6px;">No proposed change reaches the live feature tables without approval here&mdash;whoever or whatever proposed it (FEATURE_TAXONOMY.md &sect;9).</p>
{banner}
{sections}
</div>"""
    return HTMLResponse(_page("Feature review queue—CFO Toolbox Admin", "Admin", body, authed=True))


def _feature_merge_confirm_page(item_id: int, form, existing: dict, vendor_names: list[str]) -> str:
    """A confirmation step interposed between Approve and the actual merge
    (Phase 1c) — Library.approve_feature_review_queue_item's existing
    exact-name-match merge logic (confirmed working in production, the
    Abacum/Aleph merge on 8/20) previously executed silently the moment an
    admin clicked Approve. Every original form field is replayed as a hidden
    input plus confirm_merge=1, so re-submitting this form is the exact same
    approve request the admin already made, just with the merge now
    explicit rather than a side effect they couldn't see coming."""
    vendors_bit = ", ".join(vendor_names) if vendor_names else "no vendor yet"
    hidden_inputs = "".join(
        f'<input type="hidden" name="{_esc(k)}" value="{_esc(str(v))}">'
        for k, v in form.multi_items() if k != "confirm_merge"
    )
    body = f"""<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin/tools/software/feature-review-queue" style="font-size:13px;color:var(--muted);">&larr; Feature review queue</a></p>
<h1>Confirm merge</h1>
<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:20px 22px;max-width:560px;">
  <p style="font-size:14.5px;line-height:1.6;margin:0 0 16px;">This feature already exists and is linked to
  <strong>{_esc(vendors_bit)}</strong>. Merge this proposal into it, or go back and change the name to keep it separate?</p>
  <div style="display:flex;gap:10px;flex-wrap:wrap;">
    <form method="post" action="/admin/tools/software/feature-review-queue/{item_id}/approve" style="margin:0;">
      {hidden_inputs}
      <input type="hidden" name="confirm_merge" value="1">
      <button type="submit" class="btn" style="font-size:14px;padding:8px 18px;">Merge</button>
    </form>
    <a href="/admin/tools/software/feature-review-queue" class="btn btn-ghost" style="font-size:14px;padding:8px 18px;text-decoration:none;">Change name</a>
  </div>
</div>
</div>"""
    return _page("Confirm merge—CFO Toolbox Admin", "Admin", body, authed=True)


@app.post("/admin/tools/software/feature-review-queue/{item_id}/approve")
async def admin_feature_review_queue_approve(request: Request, item_id: int):
    """The approve form doubles as the edit form (see
    _feature_review_queue_item_card) — every field it submits is rebuilt
    into a payload here and passed as override_payload, so a verbatim
    approval and an edited one go through the exact same code path;
    Library.approve_feature_review_queue_item decides 'approved' vs. 'edited'
    by comparing against the stored payload."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    lib = _lib()
    try:
        item = lib.get_feature_review_queue_item(item_id)
        if item is None:
            return RedirectResponse("/admin/tools/software/feature-review-queue?msg=Not+found.", status_code=303)
        stored_payload = item["payload"]
        override = {"category_id": item["category_id"]}
        if "feature_id" in form:
            override["feature_id"] = int(form["feature_id"])
        else:
            override["feature"] = {
                "name": (form.get("feature_name") or "").strip(),
                "pointer_note": (form.get("pointer_note") or "").strip(),
            }
        n_links = int(form.get("n_links") or 0)
        links = []
        for i in range(n_links):
            links.append({
                "tool_id": int(form.get(f"link_{i}_tool_id") or 0),
                "availability": (form.get(f"link_{i}_availability") or "native").strip(),
                "ai_enabled": 1 if form.get(f"link_{i}_ai_enabled") == "1" else 0,
                "verified_as_of": (form.get(f"link_{i}_verified_as_of") or "").strip(),
                "note": (form.get(f"link_{i}_note") or "").strip(),
                "source_url": (form.get(f"link_{i}_source_url") or "").strip(),
            })
        override["links"] = links

        # Merge confirmation step (Phase 1c): a new_feature proposal whose
        # (possibly edited) name matches an existing feature in the category
        # would otherwise merge silently inside approve_feature_review_queue_item
        # — confirmed working, but invisible, in production (the Abacum/
        # Aleph merge, 8/20). If this is a new-feature proposal, the name
        # collides, and the admin hasn't already confirmed (confirm_merge=1
        # on a resubmit from the confirmation page below), stop here and
        # show the merge/change-name choice instead of executing anything.
        if override.get("feature") and form.get("confirm_merge") != "1":
            feature_name = override["feature"]["name"]
            existing = lib.find_category_feature_by_name(item["category_id"], feature_name) if feature_name else None
            if existing:
                vendor_names = [t["name"] for t in lib.list_tools_linked_to_feature(existing["id"])]
                return HTMLResponse(_feature_merge_confirm_page(item_id, form, existing, vendor_names))

        # "Edited" vs. verbatim compares only the fields the form actually
        # exposes for editing — not note/source_url (pass-through hidden
        # fields, not rendered as inputs) and not key presence, so a scan
        # proposal's payload (which never sets note/source_url) isn't
        # mislabeled "edited" just because the rebuilt override always
        # carries those keys.
        def _comparable(p: dict) -> tuple:
            f = p.get("feature") or {}
            return (
                p.get("feature_id"), f.get("name", ""), f.get("pointer_note", ""),
                tuple(sorted(
                    (l.get("tool_id"), l.get("availability", "native"),
                     int(l.get("ai_enabled") or 0), l.get("verified_as_of", ""))
                    for l in p.get("links", [])
                )),
            )
        was_edited = _comparable(override) != _comparable(stored_payload)
        lib.approve_feature_review_queue_item(
            item_id, override_payload=(override if was_edited else None),
        )
    except ValueError as e:
        return RedirectResponse(f"/admin/tools/software/feature-review-queue?msg={quote(str(e))}", status_code=303)
    finally:
        lib.close()
    msg = "Approved (edited)." if was_edited else "Approved."
    return RedirectResponse(f"/admin/tools/software/feature-review-queue?msg={quote(msg)}", status_code=303)


@app.post("/admin/tools/software/feature-review-queue/{item_id}/deny")
async def admin_feature_review_queue_deny(request: Request, item_id: int):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    resolution_note = (form.get("resolution_note") or "").strip()
    lib = _lib()
    try:
        lib.deny_feature_review_queue_item(item_id, resolution_note)
    except ValueError as e:
        return RedirectResponse(f"/admin/tools/software/feature-review-queue?msg={quote(str(e))}", status_code=303)
    finally:
        lib.close()
    return RedirectResponse("/admin/tools/software/feature-review-queue?msg=Denied.", status_code=303)


