def _tl_recent_highlight_item(index: int, icon_svg: str, type_label: str, item: dict | None) -> str:
    """One tile of the homepage's "Recent highlights" 2-column grid
    (Homepage Restructure design file) — one representative entry per type:
    a small icon + type-label row, the title (linked when a URL exists),
    venue/date metadata, and the entry's own description. Collapses to
    nothing when the type has zero entries at all (`item` is None), same
    empty-column convention /thought-leadership's own column() uses."""
    if not item:
        return ""
    meta_bits = [b for b in (item.get("venue"), item.get("date_label")) if b]
    meta_html = (f'<div style="font-size:12px;color:var(--muted);margin-bottom:8px;">'
                 f'{" &middot; ".join(_esc(b) for b in meta_bits)}</div>') if meta_bits else ""
    title_html = (f'<a href="{_esc(item["url"])}" target="_blank" rel="noopener" style="font-family:var(--font-head);'
                  f'font-weight:600;font-size:15px;color:var(--ink);line-height:1.4;display:block;margin-bottom:4px;'
                  f'text-decoration:none;">{_esc(item["title"])}</a>'
                  if item.get("url") else
                  f'<div style="font-family:var(--font-head);font-weight:600;font-size:15px;color:var(--ink);'
                  f'line-height:1.4;margin-bottom:4px;">{_esc(item["title"])}</div>')
    desc_html = (f'<p style="font-size:13px;line-height:1.55;color:var(--muted);margin:0;">{_esc(item["description"])}</p>'
                 if item.get("description") else "")
    # Badge built inline rather than via _card_icon() — that helper's
    # margin-bottom:14px (meant for a badge stacked above a title) would
    # throw off align-items:center in this icon-beside-label row.
    bg, stroke = _CARD_ICON_STYLES[index % 3]
    badge = (
        f'<div style="width:32px;height:32px;border-radius:8px;background:{bg};'
        f'display:flex;align-items:center;justify-content:center;flex-shrink:0;">'
        f'<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="{stroke}" '
        f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{icon_svg}</svg></div>'
    )
    return (
        f'<div>'
        f'<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">'
        f'{badge}'
        f'<div style="font-size:11.5px;font-weight:600;letter-spacing:.06em;color:var(--muted);'
        f'text-transform:uppercase;">{_esc(type_label)}</div></div>'
        f'{title_html}{meta_html}{desc_html}</div>'
    )


def _sort_key_from_date_label(date_label: str) -> str:
    """Derive a YYYY-MM sort_key from the free-text date_label admins type
    (e.g. 'Jun 2026' or 'June 2026'). Pure function of date_label — safe to
    recompute on every save. Blank or unparseable input returns '' rather
    than blocking the save: an entry with no resolvable date floats to the
    top of its section, the same convention already used intentionally for
    the standing "Cash Flow Show — Full Episode Feed" link. See
    _tl_parse_warning below for the admin-facing note when that happens
    for a non-blank date_label (i.e. likely a typo, not deliberate)."""
    s = date_label.strip()
    if not s:
        return ""
    for fmt in ("%b %Y", "%B %Y"):  # "Jun 2026", "June 2026"
        try:
            dt = datetime.strptime(s, fmt)
            return f"{dt.year:04d}-{dt.month:02d}"
        except ValueError:
            continue
    return ""


def _tl_parse_warning(item: dict) -> str:
    """Inline note on the admin form when a non-blank date_label didn't
    parse into a sort_key — distinguishes an accidental typo from the
    deliberate blank-date_label convention (which needs no warning)."""
    date_label = (item.get("date_label") or "").strip()
    sort_key = item.get("sort_key") or ""
    if date_label and not sort_key:
        # Same advisory-amber tone as the "Needs verification" badges/verify
        # banners elsewhere in admin (#fef3c7/#92400e/#fde68a) — see
        # linklib/brand_check.py's AUX_COLORS for why this is a documented,
        # distinct-from-`--caution` tone rather than a new hue.
        return (
            '<p style="margin:-8px 0 0;padding:8px 12px;background:#fef3c7;border:1px solid #fde68a;'
            'border-radius:8px;font-size:12px;color:#92400e;">'
            "Date didn&rsquo;t parse as Mon YYYY — this entry will float to the top of its section.</p>"
        )
    return ""


def _tl_form_fields(item: dict | None = None) -> str:
    item = item or {}
    type_opts = "".join(
        f'<option value="{t}"{" selected" if item.get("type") == t else ""}>{label}</option>'
        for t, label in _TL_TYPES
    )
    checked = "checked" if item.get("needs_synopsis") else ""
    return f"""  <div>
    <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">Type *</label>
    <select name="type" required style="width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;">
      {type_opts}
    </select>
  </div>
  <div>
    <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">Title *</label>
    <input name="title" required maxlength="300" value="{_esc(item.get('title', ''))}"
      style="width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;"
      placeholder="Role/capacity (Host, Co-Chair, Guest, …) goes inline here, e.g. &quot;Cash Cycle Demo Day—Co-Chair&quot;">
  </div>
  <div>
    <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">URL</label>
    <input name="url" type="url" maxlength="500" value="{_esc(item.get('url', ''))}"
      style="width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;"
      placeholder="https://… (leave blank to render as unlinked text)">
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;">
    <div>
      <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">Source / venue</label>
      <input name="venue" maxlength="200" value="{_esc(item.get('venue', ''))}"
        style="width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;"
        placeholder="Publication or host org">
    </div>
    <div>
      <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">Date label</label>
      <input name="date_label" maxlength="50" value="{_esc(item.get('date_label', ''))}"
        style="width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;"
        placeholder="Mon YYYY, e.g. Jun 2026 — leave blank for a standing, undated link">
    </div>
  </div>
  {_tl_parse_warning(item)}
  <div>
    <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">Display order (tiebreaker)</label>
    <input name="display_order" type="number" value="{item.get('display_order', '') if item else ''}"
      style="width:180px;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;"
      placeholder="Leave blank — auto-assigned">
  </div>
  <p style="margin:-8px 0 0;font-size:12px;color:var(--muted);">
    Date label decides order (newest first) — it's parsed into the render order automatically, so you
    don&rsquo;t need to think about sort order when filling it in. Leave Date label blank for a standing
    link with no single date (e.g. a full episode feed); it floats to the top of its column. Display order
    is a rare manual override — only needed if two entries share the same month and you want to control
    which one shows first; leave it blank otherwise and the next value is assigned automatically.
  </p>
  <div>
    <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">Description</label>
    <textarea name="description" maxlength="500" rows="3"
      style="width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;resize:vertical;"
      placeholder="1-2 sentence synopsis in Brian's voice">{_esc(item.get('description', ''))}</textarea>
  </div>
  <div>
    <label style="display:flex;align-items:center;gap:8px;font-size:14px;color:var(--navy);">
      <input type="checkbox" name="needs_synopsis" value="1" {checked}>
      Needs synopsis (shows a "Synopsis pending" placeholder instead of the description above)
    </label>
  </div>
  <div>
    <label style="display:flex;align-items:center;gap:8px;font-size:14px;color:var(--navy);">
      <input type="checkbox" name="featured_home" value="1" {"checked" if item.get("featured_home") else ""}>
      Feature on homepage
    </label>
    <p style="margin:4px 0 0 26px;font-size:12px;color:var(--muted);">
      Represents this entry's type (Writing, Speaking &amp; Events, Podcasts, or Press) in the homepage's
      4-column breakdown. If more than one entry of the same type is checked, the most recently updated one
      wins. Leave unchecked and the most recent entry of that type is used automatically.
    </p>
  </div>"""


@app.get("/admin/thought-leadership", response_class=HTMLResponse)
def admin_thought_leadership(request: Request, type: str = ""):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        items = lib.list_thought_leadership(type=type or None)
    finally:
        lib.close()

    def _row(it: dict) -> str:
        url_cell = (f'<a href="{_esc(it["url"])}" target="_blank" rel="noopener" style="word-break:break-all;">'
                    f'{_esc(it["url"][:50])}{"…" if len(it["url"]) > 50 else ""}</a>') if it["url"] else "—"
        # A non-blank date_label with no sort_key means it didn't parse as
        # Mon YYYY — flag it here too, not just on the edit form, since this
        # is the page an admin scans to spot something off at a glance.
        date_warning = (' <span title="Didn&rsquo;t parse — floats to top of its section" '
                         'style="color:#92400e;">&#9888;</span>') if it['date_label'] and not it['sort_key'] else ''
        return f"""<tr style="border-top:1px solid var(--line);">
  <td style="padding:10px 12px;font-size:13px;color:var(--muted);">{_esc(_TL_TYPE_LABELS.get(it['type'], it['type']))}</td>
  <td style="padding:10px 12px;font-weight:600;">{_esc(it['title'])}</td>
  <td style="padding:10px 12px;font-size:13px;color:var(--muted);">{_esc(it['venue']) or '—'}</td>
  <td style="padding:10px 12px;font-size:13px;color:var(--muted);white-space:nowrap;">{_esc(it['date_label']) or '—'}{date_warning}</td>
  <td style="padding:10px 12px;font-size:13px;color:var(--muted);">{url_cell}</td>
  <td style="padding:10px 12px;white-space:nowrap;">
    <a href="/admin/thought-leadership/{it['id']}/edit" class="btn btn-ghost" style="padding:5px 12px;font-size:13px;">Edit</a>
    <form method="post" action="/admin/thought-leadership/{it['id']}/delete" style="display:inline;"
          onsubmit="return confirm('Delete &quot;{_esc(it['title'])}&quot; from thought leadership?');">
      <button type="submit" class="btn btn-ghost" style="padding:5px 12px;font-size:13px;color:#b91c1c;border-color:#fca5a5;margin-left:4px;">Delete</button>
    </form>
  </td>
</tr>"""

    rows = "".join(_row(it) for it in items) or \
        '<tr><td colspan="6" style="padding:20px;color:var(--muted);">No entries yet.</td></tr>'

    def _filter_link(t: str, label: str) -> str:
        active = t == type
        href = "/admin/thought-leadership" + (f"?type={t}" if t else "")
        style = "font-weight:700;color:var(--navy);" if active else "color:var(--muted);"
        return f'<a href="{href}" style="font-size:13px;margin-right:14px;{style}">{label}</a>'

    filters = _filter_link("", "All") + "".join(_filter_link(t, label) for t, label in _TL_TYPES)

    body = f"""<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">
  <h1>Thought leadership</h1>
  <a href="/admin/thought-leadership/new" class="btn" style="font-size:14px;padding:8px 18px;">+ Add entry</a>
</div>
<p style="margin:0 0 16px;"><a href="/thought-leadership" style="font-size:13px;color:var(--muted);">View on public site →</a></p>
<div style="margin-bottom:16px;">{filters}</div>
<div style="overflow-x:auto;">
<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;">
<thead><tr style="background:var(--accent-light);">
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Type</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Title</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Source / venue</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Date</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">URL</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Actions</th>
</tr></thead>
<tbody>{rows}</tbody>
</table>
</div>
<p style="font-size:12px;color:var(--muted);margin:16px 0 0;">
  The Abacum AI Summit entry (Speaking &amp; Events) isn&rsquo;t listed here&mdash;it&rsquo;s a one-off with photos,
  hardcoded on the public page rather than migrated. See CLAUDE.md.
</p>
</div>"""
    return HTMLResponse(_page("Thought leadership—Admin", "", body, authed=True))


