def _run_tool_research(tool_id: int) -> bool:
    """Automated agent-taxonomy research for one Software entry — the shared
    drafting logic behind both trigger points confirmed for the
    search-overhaul automation follow-up: fired off-request via
    BackgroundTasks right after a tool is added (admin add-form and the
    public /tools/submit form), and re-run synchronously from the "Refresh AI
    research" admin button (its return value drives that route's success/
    failure banner; BackgroundTasks callers just ignore it). Mirrors the
    other _*_background jobs here (off-request, best-effort, DB-open-per-call)
    — a slow or failed research call never blocks the tool from going live.
    The field it writes lands via the needs_verification-flagged draft path
    (set_tool_agent_taxonomy_draft), never auto-confirmed.

    Used to also draft standalone-vs-bundled tool_features rows in the same
    call — dropped in the Feature Taxonomy Phase 1b PR 2 legacy retirement
    (CLAUDE.md's "no dead data" note) along with the table itself."""
    lib = _lib()
    try:
        tool = lib.get_tool(tool_id)
        if not tool:
            return False
        from linklib import enrich as enrich_mod
        from linklib.voice_settings import VoicePromptMissing, require_voice_setting
        try:
            voice_core = require_voice_setting(lib, "voice_core")
        except VoicePromptMissing as e:
            print(f"[_run_tool_research:{tool_id}] aborted: {e}")
            return False
        result = enrich_mod.generate_tool_agent_taxonomy(
            tool["name"], tool["url"], tool.get("description", ""), model=lib.get_enrich_model(),
            voice_core=voice_core)
        if result is None:
            return False
        wrote_anything = False
        if result.agent_taxonomy_note.strip():
            lib.set_tool_agent_taxonomy_draft(
                tool_id, result.agent_taxonomy_note,
                needs_verification=int(result.agent_taxonomy_needs_verification),
                ai_confident=int(result.confident),
                low_confidence=int(result.low_confidence),
            )
            lib.set_entity_citations("tool", tool_id, "agent_taxonomy",
                                     result.citations, model=result.model)
            # Whole-record profile signoff (2026-08 amendment) — this fresh
            # draft's own trigger for the auto-link: force needs_review to 1
            # when this draft itself landed agent_taxonomy_needs_verification
            # on 1 (an unconfident/uncertain result), same as the OR pattern
            # in admin_tools_edit_submit but applied here since this call has
            # no checkbox/request of its own to OR against — never forces to
            # 0, only ever adds the flag, same as Communities' own pattern.
            if result.agent_taxonomy_needs_verification:
                lib.set_tool_needs_review(tool_id, 1)
            wrote_anything = True
        if wrote_anything or result.cost_usd:
            lib.record_enrichment_cost(None, result.model, result.input_tokens,
                                       result.output_tokens, result.cost_usd)
        backup.maybe_backup(DB_PATH)
        return True
    except Exception:
        return False
    finally:
        lib.close()


@app.post("/admin/tools/software/new")
async def admin_tools_new_submit(request: Request, background_tasks: BackgroundTasks):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    name = (form.get("name") or "").strip()
    url = (form.get("url") or "").strip()
    description = (form.get("description") or "").strip()
    summary = (form.get("summary") or "").strip()
    categories = [v.strip() for v in form.getlist("categories") if v.strip()]
    advisor = 1 if form.get("advisor") == "1" else 0
    promoted = 1 if form.get("promoted") == "1" else 0
    vendor_email = (form.get("vendor_email") or "").strip()
    warm_intro_enabled = 1 if form.get("warm_intro_enabled") == "1" else 0
    vendor_name = (form.get("vendor_name") or "").strip()
    if not (name and url and description and summary):
        raise HTTPException(status_code=400, detail="Name, URL, description, and summary are required.")
    # Citations-API grounding fix, Phase 2 — closes a real gap: this form's
    # Generate-description button used to have nowhere to record
    # needs_verification/confidence/citations at all, since add_tool() never
    # accepted them and the form carried none of the ai-drafted-* hidden
    # inputs. Same "fresh draft this submit" convention as the edit-submit
    # route below (_ai_drafted_field_names/_ai_drafted_field_confidence),
    # just evaluated once at creation instead of on every resave.
    ai_drafted = _ai_drafted_field_names(form)
    ai_confidence = _ai_drafted_field_confidence(form)
    ai_low_confidence = _ai_drafted_field_low_confidence(form)
    description_needs_verification = 1 if ({"description", "summary"} & ai_drafted) else 0
    description_confident = (
        int(ai_confidence["description"]) if "description" in ai_drafted and "description" in ai_confidence
        else None
    )
    description_low_confidence = (
        int(ai_low_confidence["description"]) if "description" in ai_drafted and "description" in ai_low_confidence
        else None
    )
    description_citations = (
        _validate_citations_payload(form.get("ai_drafted_citations") or "")
        if "description" in ai_drafted else []
    )
    citations_model = (form.get("ai_drafted_citations_model") or "").strip()
    lib = _lib()
    try:
        name_dup = lib.find_tool_name_duplicate(name)
        tool_id = lib.add_tool(name, description, url, categories, approved=1, advisor=advisor,
                                promoted=promoted, vendor_email=vendor_email,
                                warm_intro_enabled=warm_intro_enabled, vendor_name=vendor_name,
                                summary=summary,
                                description_needs_verification=description_needs_verification,
                                description_ai_confident=description_confident,
                                description_low_confidence=description_low_confidence)
        if description_citations:
            lib.set_entity_citations("tool", tool_id, "description", description_citations, model=citations_model)
    except DuplicateURLError as e:
        raise HTTPException(status_code=400, detail=_duplicate_url_message(e, f"/tools/software/{e.slug}/edit"))
    finally:
        lib.close()
    background_tasks.add_task(_run_tool_research, tool_id)
    redirect_url = "/tools/software"
    if name_dup:
        redirect_url += f"?warn={quote(_name_duplicate_warning(name_dup))}"
    return RedirectResponse(redirect_url, status_code=303)


