@app.get("/admin/checks", response_class=HTMLResponse)
def admin_checks(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)
    from webapp import checks as _checks
    results = _checks.run_all()

    live = [r for r in results if r["where"] == "In-app"]
    passing = sum(1 for r in live if r["ok"])
    failing = [r for r in live if r["ok"] is False]

    if not live:
        summary = ""
    elif failing:
        summary = (f'<p style="background:#fee2e2;color:#b91c1c;border:1px solid #fca5a5;border-radius:10px;'
                   f'padding:10px 16px;font-size:14px;margin:-4px 0 20px;">{len(failing)} live check'
                   f'{"s" if len(failing) != 1 else ""} failing&mdash;details below.</p>')
    else:
        summary = (f'<p style="background:#d1fae5;color:#065f46;border:1px solid #6ee7b7;border-radius:10px;'
                   f'padding:10px 16px;font-size:14px;margin:-4px 0 20px;">&#10003; All {passing} live checks passing.</p>')

    def _status(r):
        if r["ok"] is True:
            return ('<span style="color:var(--good);font-weight:600;">&#10003; Passing</span>', "var(--good)")
        if r["ok"] is False:
            return ('<span style="color:var(--alert);font-weight:600;">&#10007; Failing</span>', "var(--alert)")
        return (f'<a href="{_checks.GITHUB_ACTIONS_URL}" target="_blank" rel="noopener" '
                f'style="color:var(--accent);font-weight:600;">Latest run &rarr;</a>', "var(--line-strong)")

    rows = ""
    for r in results:
        badge, bar = _status(r)
        where = ('<span style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;">'
                 f'{r["where"]}</span>')
        rows += (
            f'<div style="border-left:3px solid {bar};background:var(--bg);border:1px solid var(--line);'
            f'border-left-width:3px;border-radius:10px;padding:12px 16px;margin-bottom:10px;">'
            f'<div style="display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;">'
            f'<span style="font-weight:600;font-size:15px;color:var(--navy);">{_esc(r["name"])}</span>'
            f'<span style="display:flex;gap:12px;align-items:baseline;">{where}{badge}</span></div>'
            f'<p style="margin:4px 0 0;font-size:13px;color:var(--ink-soft);line-height:1.5;">{_esc(r["what"])}</p>'
            f'<p style="margin:3px 0 0;font-size:12px;color:var(--muted);line-height:1.45;">{_esc(r["detail"])}</p>'
            f'</div>')

    body = f"""<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<h1>Checks</h1>
<p style="color:var(--ink-soft);margin:-4px 0 18px;font-size:15px;line-height:1.6;">The automated guards that keep the site honest. <strong>Every check here runs on each commit</strong> in the <a href="{_checks.GITHUB_ACTIONS_URL}" target="_blank" rel="noopener" style="color:var(--accent);">GitHub QA workflow</a>; the deterministic ones (<em>Live + CI</em>) also run live on this page so you get an instant read.</p>
{summary}
{rows}
<p style="margin:18px 0 0;font-size:12.5px;color:var(--muted);">CI status for every check, including the ones above: <a href="{_checks.GITHUB_ACTIONS_URL}" target="_blank" rel="noopener" style="color:var(--accent);">view the latest QA run &rarr;</a></p>
</div>"""
    return HTMLResponse(_page("Checks—Admin", "Admin", body, authed=True))


def _relative_age(iso: str) -> str:
    """"3h ago" for a stored ISO timestamp; "" when it can't be parsed.

    Staleness is shown, never acted on: an old but passing check stays green.
    How long ago it ran is context for the reader, not a fourth state.
    """
    if not iso:
        return ""
    try:
        then = datetime.fromisoformat(iso)
    except Exception:
        return ""
    if then.tzinfo is None:
        then = then.replace(tzinfo=timezone.utc)
    secs = (datetime.now(timezone.utc) - then).total_seconds()
    if secs < 0:
        return "just now"          # clock skew, not a future check
    if secs < 90:
        return "just now"
    if secs < 3600:
        return f"{int(secs // 60)}m ago"
    if secs < 86400:
        return f"{int(secs // 3600)}h ago"
    return f"{int(secs // 86400)}d ago"


def _job_run_banner(job_name: str) -> str:
    """Durability audit item 3 — "last run: outcome, N ago" for one
    _JOB_STATE-backed background job, read from the durable job_run_log
    table rather than the in-process _JOB_STATE dict (which a redeploy or
    crash wipes with no trace). Same banner pattern as
    _backup_status_banner/_integrity_status_banner: green on success, amber
    on a deliberate stop or "never run", coral on failure — loud, not
    routine. A row stuck at status='running' with no finished_at is what a
    crash mid-run looks like, called out explicitly rather than shown as a
    normal in-progress state (this banner never reflects LIVE progress —
    that's still _JOB_STATE/the poll endpoint each page already has).

    2026-08 wrap-up sprint item 3 fix: that "never finished — likely
    interrupted by a deploy or crash" interpretation is only true when
    nothing live actually corresponds to the open row — confirmed in
    production twice, this banner rendered the crash interpretation
    directly above the same page's own genuinely-in-progress status panel,
    because it never checked _JOB_STATE at all before assuming an open row
    meant a crash. A run should only read as "never finished" when there's
    no live process behind it; when _JOB_STATE says this job is currently
    running, the open row IS that live run, not evidence of a crash — so
    this now checks `_job_get(job_name)["running"]` first and renders the
    ordinary in-progress line instead."""
    lib = _lib()
    try:
        last = lib.latest_job_run(job_name)
    finally:
        lib.close()
    amber_wash, amber_border, amber_text = "#fef3c7", "#fde68a", "#92400e"
    coral_wash, coral = "var(--coral-wash)", "var(--coral)"
    seafoam_wash, seafoam = "var(--seafoam-wash)", "var(--seafoam)"
    blue_wash, blue_border, blue_text = "#eff6ff", "#bfdbfe", "#1d4ed8"

    if not last:
        bg, border, color = amber_wash, amber_border, amber_text
        html = "No run recorded yet."
    elif last["status"] == "running" and not last.get("finished_at") and _job_get(job_name).get("running"):
        bg, border, color = blue_wash, blue_border, blue_text
        ago = _relative_age(last["started_at"])
        html = f'Last run started {ago or "recently"} and is still in progress&mdash;see the live status above.'
    elif last["status"] == "running" and not last.get("finished_at"):
        bg, border, color = amber_wash, amber_border, amber_text
        ago = _relative_age(last["started_at"])
        html = f'Last run started {ago or "recently"}, never finished&mdash;likely interrupted by a deploy or crash. Safe to start again; earlier progress isn&rsquo;t lost (see the job&rsquo;s own resumability notes above).'
    elif last["status"] == "success":
        bg, border, color = seafoam_wash, seafoam, "inherit"
        ago = _relative_age(last["finished_at"] or last["started_at"])
        summary = _esc(last.get("summary") or "")
        html = f'Last run: <strong>succeeded</strong>, {ago}{f"&mdash;{summary}" if summary else ""}.'
    elif last["status"] == "stopped":
        bg, border, color = amber_wash, amber_border, amber_text
        ago = _relative_age(last["finished_at"] or last["started_at"])
        summary = _esc(last.get("summary") or "")
        html = f'Last run: <strong>stopped</strong> by an admin, {ago}{f"&mdash;{summary}" if summary else ""}.'
    else:
        bg, border, color = coral_wash, coral, "inherit"
        ago = _relative_age(last["finished_at"] or last["started_at"])
        err = _esc(last.get("error") or "no error message recorded")
        html = f'Last run: <strong>failed</strong>, {ago}&mdash;{err}.'
    return (f'<div style="background:{bg};border:1px solid {border};color:{color};border-radius:10px;'
            f'padding:10px 16px;margin:0 0 16px;font-size:13px;line-height:1.5;">{html}</div>')


# True stoplight colours, a sanctioned narrow exception to the palette — see
# BRAND.md §Color. The semantic tokens were tried first and --good is navy,
# which is the site's dominant colour and so reads as ordinary text rather
# than a health signal. Scoped to these three dots and nowhere else; every
# other pass/warn/error use stays on --good/--caution/--alert.
#
# The red is the existing destructive-action red (#b91c1c, the Delete/Remove
# buttons) rather than a second red, so "red = bad" stays one value sitewide.
#
# Amber is strictly "couldn't be tested". A passing check stays green however
# old it is, so there is no staleness tier.
_COOKIE_STATE_STYLES = {
    "working": ("#15803D", "working"),
    "expired": ("#b91c1c", "expired"),
    "unknown": ("#CA8A04", "inconclusive"),
}


def _cookie_status_panel(cookies, status: dict) -> str:
    """Always-on summary of the last stored probe result, one row per domain.

    Reads the persisted `auth_cookie_status` record, so it survives reloads and
    shows the last known result rather than going blank until someone clicks
    Re-check. Distinct from the feed table's Cookie checkbox by design: that is
    a static declaration that a feed needs a cookie, this is the dynamic health
    of the cookie itself. Different surface, different shape (a dot, not a
    checkbox), no seafoam, so the two don't read as one control.
    """
    rows = ""
    for dom in cookies:
        s = status.get(dom) or {}
        ok = s.get("ok")
        key = "working" if ok else ("unknown" if ok is None else "expired")
        color, label = _COOKIE_STATE_STYLES[key]
        detail = s.get("detail") or "not checked yet"
        age = _relative_age(s.get("checked_at", ""))
        rows += (
            f'<div class="ck-row">'
            f'<span class="ck-dot" style="background:{color};" aria-hidden="true"></span>'
            f'<span class="ck-dom">{_esc(dom)}</span>'
            f'<span class="ck-state">{label}</span>'
            f'<span class="ck-detail">{_esc(detail)}</span>'
            f'<span class="ck-age">{_esc(age)}</span>'
            f'</div>')
    return (f'<div class="ck-panel" role="group" aria-label="Subscriber cookie status">'
            f'{rows}</div>')


def _auth_cookie_controls(request: Request,
                          background_tasks: BackgroundTasks) -> tuple[str, str]:
    """Subscriber-cookie status control, shown at the top of
    /admin/library/feeds. It's a feed-specific tool — it probes a recent post
    per paywalled source to confirm that source's subscriber cookie still
    fetches full text — so it lives with feed management rather than on the
    Library hub, where it sat before the Feeds page existed. Only rendered
    when at least one LINKLIB_COOKIE_<DOMAIN> var is set. Kicks a background
    re-check when the stored status is missing or stale.

    Phase 1 removed the permanent green "Subscriber access" status box that
    used to sit on the Admin hub — the manual re-check trigger and the
    underlying check logic (authcheck.check_auth_cookies) are unchanged, but
    the UI only surfaces a colored panel with per-domain detail when a cookie
    has actually gone stale (any_bad). Otherwise this renders just a compact
    "Re-check" control, so there's still a way to trigger a check by hand
    without a status box sitting there permanently.

    Returns (button_html, panel_html). The button now sits beside "+ Add feed"
    in the page header, so the panel no longer renders a second copy of it —
    two identical triggers a few hundred pixels apart read as two different
    actions. Both halves are "" when no cookies are configured.
    """
    from linklib.extract import _auth_cookies
    cookies = _auth_cookies()
    if not cookies:
        return "", ""   # feature dormant until cookies are configured

    from linklib import authcheck
    lib = _lib()
    try:
        status = authcheck.get_auth_status(lib)
    finally:
        lib.close()

    age = authcheck.status_age_seconds(status)
    if age is None or age > 12 * 3600:          # stale or never run -> refresh in background
        background_tasks.add_task(_auth_recheck_background)

    stale = authcheck.stale_domains(status)
    any_bad = bool(stale)

    recheck_form = ('<form method="post" action="/admin/auth/recheck" style="margin:0;">'
                     '<button type="submit" class="btn btn-ghost" style="font-size:13px;padding:6px 14px;">'
                     'Re-check subscriber access</button></form>')

    summary = _cookie_status_panel(cookies, status)
    if not any_bad:
        return recheck_form, summary

    from linklib.extract import _cookie_env_var
    stale_vars = ", ".join(f"<code>{_esc(_cookie_env_var(d))}</code>" for d in stale)
    refresh_steps = (f"""<p style="font-size:13px;color:var(--ink-soft);margin:10px 0 6px;">To refresh an expired cookie:</p>
<ol style="font-size:13px;color:var(--ink-soft);line-height:1.55;margin:0 0 6px;padding-left:20px;">
<li>Log into the site.</li>
<li>Open DevTools &rarr; <strong>Network</strong>, then reload.</li>
<li>Click the request to the domain.</li>
<li>Copy the full <code>Cookie:</code> header.</li>
<li>Update {stale_vars} in Railway &rarr; Variables.</li>
</ol>""")

    # Which domains are stale is already shown, in colour, in the summary
    # above — this panel now carries only what that can't: the fix.
    panel = f"""<div style="background:var(--coral-wash);border:1px solid var(--coral);border-radius:12px;padding:16px 18px;margin:0 0 22px;">
  <div style="font-family:var(--font-head);font-weight:600;font-size:15px;color:var(--navy);">Subscriber cookie expired</div>
  {refresh_steps}
</div>"""
    return recheck_form, summary + panel


@app.get("/admin", response_class=HTMLResponse)
def admin_page(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)

    from webapp import tasks as _tasks
    lib = _lib()
    try:
        task_counts = _tasks.open_task_counts(lib)
        password_nudge_html = _password_change_nudge_html(lib, request)
    finally:
        lib.close()

    def _card(href, title, desc, badge_html=""):
        return (
            f'<a href="{href}" style="display:block;background:var(--surface);border:1px solid var(--line);'
            f'border-radius:14px;padding:20px 22px;text-decoration:none;">'
            f'<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;">'
            f'<span style="display:flex;align-items:center;gap:8px;">'
            f'<span style="font-family:var(--font-head);font-weight:600;font-size:17px;color:var(--navy);letter-spacing:-0.01em;">{title}</span>'
            f'{badge_html}</span>'
            f'<span style="color:var(--navy);font-size:18px;line-height:1;">&rarr;</span></div>'
            f'<p style="margin:6px 0 0;font-size:14px;color:var(--muted);line-height:1.5;">{desc}</p></a>'
        )

    # _group_html's `items` accepts either a plain (href, title, desc) tuple
    # — rendered as a normal _card() link, navigating straight to that tool's
    # own page like every group already did — or a pre-rendered HTML string
    # (a nested _group_html() call's own output), included as-is. That's how
    # CFO Toolbox nests FP&A Buddy as a real sub-group below: the exact same
    # <details>/<summary> disclosure mechanism Inbox already uses, just
    # called a second time and dropped into the parent's item list, with no
    # new mechanism needed. `badge_hrefs` lets a caller show an aggregate
    # badge covering more than just this group's own direct items — CFO
    # Toolbox uses it to fold in FP&A Buddy's and Library's hrefs too, so the
    # header badge reflects the true pending count across everything nested
    # inside it, not just its 5 direct children. `nested=True` gives a
    # sub-group a visually lighter treatment (smaller padding/caret, filled
    # --bg instead of transparent) so it reads as nested rather than a
    # sibling of the same visual weight.
    def _group_html(gname, gdesc, items, badge_hrefs=None, nested=False):
        cards = "".join(
            item if isinstance(item, str) else
            _card(item[0], item[1], item[2], _badge_for_href(item[0], task_counts.get(item[0], 0)))
            for item in items
        )
        flat_hrefs = badge_hrefs if badge_hrefs is not None else [item[0] for item in items if not isinstance(item, str)]
        group_badge_html = _group_badge(task_counts, flat_hrefs)
        # Every group/sub-group defaults to COLLAPSED on load, Inbox
        # included — reversed 2026-09 from an earlier "Inbox always open,
        # any group with a nonzero badge also starts open" rule (flagging
        # the reversal explicitly rather than silently, per CLAUDE.md's own
        # standing practice for this). That earlier rule was itself a
        # deliberate fix for a real incident: a pending name-duplicate pair
        # went unnoticed inside a collapsed sub-group, with nothing but a
        # small aggregate number on the parent's summary to hint at it —
        # see CLAUDE.md's LiveFlow/Runway note. Reversing it does NOT bring
        # that failure mode back: `.admin-group[open] .group-badge{display:
        # none;}` only ever hides a group's badge once it's opened, so a
        # collapsed-by-default group with a real pending item still shows
        # its badge number on the summary row, unhidden, exactly where the
        # incident's own root cause (a badge sitting collapsed) says to
        # look. Brian's explicit call: badges are the review-inbox signal;
        # auto-expanding on top of that duplicated the same information as
        # an intrusive default rather than a genuinely different safeguard.
        return _disclosure_group(
            gname,
            f'<p style="margin:0 0 14px;font-size:13.5px;color:var(--muted);">{gdesc}</p>'
            f'<div style="display:grid;gap:14px;">{cards}</div>',
            count_label=f'{len(items)} {"tool" if len(items) == 1 else "tools"}',
            badge_html=group_badge_html,
            open=False,
            nested=nested,
        )

    # Library used to get its own always-expanded card floating above every
    # group; it's now a direct link inside CFO Toolbox instead (Phase 6 —
    # "CFO Toolbox → Library" is the new entry point for archive/library
    # management). Its own aggregate badge (from all _LIBRARY_TOOLS
    # hrefs) is unchanged — just relocated.
    library_hrefs = [href for href, _, _ in _LIBRARY_TOOLS]
    library_link_card = _card("/admin/library", "Library",
                              f"Build, curate, enrich, and back up your archive&mdash;{len(_LIBRARY_TOOLS)} tools.",
                              _group_badge(task_counts, library_hrefs))

    # Compare Redesign Phase 2 — spans both Software and Communities Compare
    # pages, so it's a direct CFO Toolbox card rather than nested under
    # either sub-group, same placement precedent as Library above.
    compare_summary_feedback_card = _card(
        "/admin/compare-summary-feedback", "Compare summary feedback",
        "Reader-flagged issues with the AI-generated Compare-page overlap/contrast summary.",
        _badge_for_href("/admin/compare-summary-feedback", task_counts.get("/admin/compare-summary-feedback", 0)),
    )

    # FP&A Buddy moves from its own standalone top-level group into a nested
    # sub-group inside CFO Toolbox — the same group, same 4 items, same
    # description, just reparented.
    fpa_hrefs = [href for href, _, _ in _FPA_BUDDY_TOOLS]
    fpa_subgroup_html = _group_html(
        "FP&A Buddy", "The Q&amp;A tool's own explainer, usage report, and feedback triage.",
        _FPA_BUDDY_TOOLS, nested=True,
    )

    # Software nests the same way (Phase 1c) — the four software-directory
    # cards, formerly flat siblings in CFO Toolbox, now read as one cluster.
    # The name-duplicates page has no card of its own (it's an inline link on
    # Software vendors' own page, not a distinct admin-nav destination), but
    # its pending count is cheap (see CLAUDE.md) and folds into this
    # sub-group's own aggregate badge via badge_hrefs, same as Library's
    # aggregate badge covers hrefs with no direct card in that group either.
    software_hrefs = [href for href, _, _ in _SOFTWARE_TOOLS] + ["/admin/tools/software/name-duplicates"]
    software_subgroup_html = _group_html(
        "Software", "Vendors, categories, and the curated feature taxonomy.",
        _SOFTWARE_TOOLS, badge_hrefs=software_hrefs, nested=True,
    )

    # Two columns on wide viewports: left carries the group Brian triages
    # most often (Inbox); right carries the three public-nav-mirroring
    # groups (Thought Leadership, CFO Toolbox, Brand/voice/content) plus the
    # System catch-all. Below the breakpoint both stacks concatenate into a
    # single-column order — unchanged from before this split.
    _LEFT_GROUPS = {"Inbox"}
    left_html = ""
    right_html = ""
    for gname, gdesc, items in _ADMIN_GROUPS:
        if gname == "CFO Toolbox":
            toolbox_hrefs = ([href for href, _, _ in items] + software_hrefs + fpa_hrefs + library_hrefs
                              + ["/admin/compare-summary-feedback"])
            html = _group_html(gname, gdesc,
                               [software_subgroup_html] + list(items)
                               + [fpa_subgroup_html, library_link_card, compare_summary_feedback_card],
                               badge_hrefs=toolbox_hrefs)
        else:
            html = _group_html(gname, gdesc, items)
        if gname in _LEFT_GROUPS:
            left_html += html
        else:
            right_html += html

    body = f"""<div class="page page-admin">
{password_nudge_html}
<style>
.admin-group summary:hover{{background:var(--surface);}}
.admin-group[open] .group-badge{{display:none;}}
.admin-cols{{display:grid;grid-template-columns:1fr;}}
@media(min-width:1024px){{.admin-cols{{grid-template-columns:1fr 1fr;gap:20px;align-items:start;}}}}
</style>
<h1>Admin</h1>
<p style="color:var(--muted);margin:4px 0 26px;">Manage the site&rsquo;s private tools.</p>
<div class="admin-cols">
<div>{left_html}</div>
<div>{right_html}</div>
</div>
</div>"""
    return HTMLResponse(_page("Admin—Brian Weisberg", "Admin", body, authed=True))


@app.get("/admin/library", response_class=HTMLResponse)
def admin_library(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)

    from webapp import tasks as _tasks
    lib = _lib()
    try:
        task_counts = _tasks.open_task_counts(lib)
    finally:
        lib.close()

    # Card-style rendering (no numbered-step badge — Phase 6 dropped the
    # implied strict top-to-bottom sequence once the tools were regrouped by
    # function rather than workflow order; see the 3-way grouping below).
    def _lib_card(href, title, desc, badge_html=""):
        return (
            f'<a href="{href}" style="display:block;background:var(--surface);border:1px solid var(--line);'
            f'border-radius:14px;padding:18px 20px;text-decoration:none;">'
            f'<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;">'
            f'<span style="display:flex;align-items:center;gap:8px;">'
            f'<span style="font-family:var(--font-head);font-weight:600;font-size:17px;color:var(--navy);letter-spacing:-0.01em;">{title}</span>'
            f'{badge_html}</span>'
            f'<span style="color:var(--navy);font-size:18px;line-height:1;">&rarr;</span></div>'
            f'<p style="margin:6px 0 0;font-size:14px;color:var(--muted);line-height:1.5;">{desc}</p></a>'
        )

    # Open Reader — a header-adjacent page action beside the H1, reusing the
    # flex + `.btn` pattern /admin/tools/software and /admin/tools/resources
    # already use for their "+ Add" links, rather than the seafoam callout box
    # that used to sit beside the flow diagram.
    #
    # Stock secondary button, no colour overrides: `.btn.btn-ghost` is already
    # navy border + navy text + transparent fill + --navy-wash hover + 10px
    # radius, which is exactly BRAND.md §"Buttons" secondary. An earlier round
    # of this build tinted it seafoam; that was wrong ("Buttons navy or ghost /
    # Make a seafoam or coral button") and is reverted here. Only size is
    # overridden, matching the "+ Add" header actions on the Toolbox admin
    # pages.
    open_reader_button = (
        '<a href="/read" class="btn btn-ghost" style="font-size:14px;padding:8px 18px;'
        'white-space:nowrap;">Open Reader</a>'
    )

    # Regrouped by function (Phase 6), not the old single top-to-bottom
    # workflow list. Archive backup was originally a standalone headingless
    # card outside all three groups — it applies to the whole archive, not
    # just "existing" content, so filing it under "Existing archive
    # management" would misdescribe it — but that read oddly once every
    # other tool had a labeled section, so it's now folded into "Archive
    # additions & backup" instead (see that section below). Enrich archive
    # stays in "Tagging" (the other genuinely ambiguous placement from the
    # Phase 6 brief) even though it also drafts summaries: it's what
    # actually applies the tag vocabulary Tag cleanup curates and Tagging
    # style teaches, so the three read as "how tags get created, taught,
    # and refined" as one cluster, even though summaries are a real second
    # output of the third.
    lib_by_href = {href: (title, desc) for href, title, desc in _LIBRARY_TOOLS}

    def _lib_quadrant(title, inner_html, hrefs=(), count_override=None):
        """One collapsible quadrant, closed by default.

        `count_override` sets the displayed tool count independently of
        `hrefs`, which otherwise drives it. Only "New content" uses it: that
        quadrant holds one _lib_card plus the two capture-method accordions,
        which are real tools a person uses even though they aren't cards, so
        the literal card count of 1 undersold it. Overriding the one label is
        deliberately narrower than redefining what counts as a "tool"
        everywhere — `hrefs` still drives the task badge, so the override
        can't desynchronise a badge from the pages it aggregates.

        This cannot affect the /admin index's counts: that page computes its
        own `count_label` from `len(items)` before calling _disclosure_group,
        which only ever receives a finished string.

        Uses the shared `_disclosure_group` component — the same group-level
        row the /admin index's sections use: bordered box, bold all-caps label
        with a muted tool count and any task badge on the left, caret
        right-aligned pointing right collapsed and down expanded. Reused rather
        than reimplemented so the two surfaces can't drift.

        The nested capture-path accordions inside New content deliberately keep
        the item-level variant (caret left of the label) — see BRAND.md
        §"UI components". Nesting is native and safe: `.disclosure-caret`'s
        rotate rule is scoped `details[open] > summary`, so an inner accordion
        can never rotate the outer quadrant's caret.
        """
        n = len(hrefs) if count_override is None else count_override
        return _disclosure_group(
            title, inner_html,
            count_label=f'{n} {"tool" if n == 1 else "tools"}' if n else "",
            badge_html=_group_badge(task_counts, list(hrefs)),
            extra_class="lib-quad",
        )

    def _lib_section(label, hrefs, desc_line):
        section_cards = "".join(
            _lib_card(h, lib_by_href[h][0], lib_by_href[h][1], _badge_for_href(h, task_counts.get(h, 0)))
            for h in hrefs
        )
        return _lib_quadrant(label, (
            f'<p style="color:var(--muted);font-size:13.5px;margin:0 0 12px;">{desc_line}</p>'
            f'<div style="display:grid;gap:12px;">{section_cards}</div>'
        ), hrefs)

    # Archive backup used to render as its own headingless card above the
    # three labeled sections — visually odd once everything else had a
    # heading (flagged live after this shipped). Folded into "Archive
    # additions" instead, first in that section, rather than kept standalone:
    # it doesn't fit "existing archive management" (see the note above), but
    # it reads fine alongside "bringing new content in" as one shared idea —
    # both are about keeping the archive intact and current, not a single
    # curation pass over content that's already there. Renamed the section to
    # "Archive additions & backup" so the heading still says what's inside it.
    # The flow diagram runs full width on its own now, between the intro and
    # the quadrant grid. Nothing shares its row (Open Reader is a header action
    # above), which also retires the phantom-margin height mismatch that row's
    # `align-items:stretch` used to produce against the diagram card's own
    # margin-bottom.
    flow_html = _content_flow_diagram()

    # Upper-left quadrant, "New content": the Manage feeds card over the two
    # capture-path accordions. Both halves keep their own shape — a _lib_card
    # and the existing accordion group — under one quadrant heading, rather
    # than being blended into a single undifferentiated block.
    saving_articles_body = f"""<p style="color:var(--muted);font-size:13.5px;margin:0 0 14px;">Where new material comes from: the subscription list the Reader pulls from, plus two capture pairs&mdash;a bookmarklet and a Share-Sheet shortcut&mdash;for saving a page by hand, one pair per destination.</p>
<div style="margin-bottom:22px;">{_lib_card(
    "/admin/library/feeds", "Manage feeds",
    "Add, rename, or remove the RSS sources behind the Reader&rsquo;s Feed view, group them into "
    "sections, and set which ones are read-only. The same list is the allowlist FP&amp;A Buddy&rsquo;s "
    "web search is restricted to.",
    _badge_for_href("/admin/library/feeds", task_counts.get("/admin/library/feeds", 0)))}</div>
<div style="font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin:0 0 8px;">Saving to the archive</div>
<p style="color:var(--muted);font-size:13.5px;margin:0 0 12px;">Both capture paths below post to <code>/save</code> with your save token baked in, so they work from any page without logging in.</p>

<details style="margin-bottom:12px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 20px;">
<summary style="cursor:pointer;font-family:var(--font-head);font-weight:600;font-size:16px;color:var(--navy);display:flex;align-items:baseline;gap:8px;"><span class="disclosure-caret">&#9654;</span>Desktop&mdash;the bookmarklet</summary>
<div style="font-size:14px;color:var(--ink-soft);line-height:1.7;margin-top:12px;">
<p style="margin:0 0 10px;">A bookmarklet is an ordinary browser bookmark whose &ldquo;URL&rdquo; is a tiny program instead of a web address. Clicking it runs the program on whatever page you're reading&mdash;it grabs that page's address and saves it to the archive.</p>
<ol style="margin:0 0 10px;padding-left:20px;">
  <li>Open <a href="/bookmarklet">/bookmarklet</a> (login-gated) and copy the <em>entire</em> snippet&mdash;click the text, <strong>Cmd+A</strong>, <strong>Cmd+C</strong>.</li>
  <li>Show the bookmarks bar (<strong>Cmd+Shift+B</strong> in Chrome), right-click an empty spot on it &rarr; <strong>Add page&hellip;</strong></li>
  <li>Name: <code>Save to CFO Library</code>. URL: <strong>paste the snippet</strong>. Save.</li>
  <li>On any article page, click it like a button &rarr; optional tags prompt &rarr; &ldquo;Saved to archive.&rdquo;</li>
</ol>
<p style="margin:0;color:var(--muted);font-size:13px;">It won't fire on browser-internal pages (new tab, chrome:// pages)&mdash;that's a browser rule. The snippet contains the save token in plaintext, so don't paste it anywhere public.</p>
</div>
</details>

<details style="margin-bottom:12px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 20px;">
<summary style="cursor:pointer;font-family:var(--font-head);font-weight:600;font-size:16px;color:var(--navy);display:flex;align-items:baseline;gap:8px;"><span class="disclosure-caret">&#9654;</span>iPhone / iPad&mdash;Share-Sheet shortcut</summary>
<div style="font-size:14px;color:var(--ink-soft);line-height:1.7;margin-top:12px;">
<p style="margin:0 0 10px;">One-time setup in the <strong>Shortcuts</strong> app (~5 minutes); afterwards &ldquo;Save to CFO Library&rdquo; appears in Safari's share sheet.</p>
<ol style="margin:0 0 10px;padding-left:20px;">
  <li>Shortcuts app &rarr; <strong>+</strong> to create a new shortcut &rarr; rename it <code>Save to CFO Library</code>.</li>
  <li>Tap the shortcut's <strong>info (&#9432;)</strong> panel &rarr; turn on <strong>Show in Share Sheet</strong>. Under the accepted types, keep <strong>URLs</strong> and <strong>Safari web pages</strong>.</li>
  <li>Add action <strong>&ldquo;Get URLs from Input&rdquo;</strong> (its input should be <em>Shortcut Input</em>).</li>
  <li>Add action <strong>&ldquo;Get Contents of URL&rdquo;</strong> and expand its options:
    <ul style="margin:4px 0;padding-left:18px;">
      <li>URL: <code>{_esc(PUBLIC_BASE)}/save{'?token=' + _esc(SAVE_TOKEN) if SAVE_TOKEN else ''}</code></li>
      <li>Method: <strong>POST</strong></li>
      <li>Request Body: <strong>JSON</strong> &rarr; add a text field named <code>url</code> whose value is the <em>URLs</em> variable from step 3.</li>
    </ul></li>
  <li>Optional: add <strong>&ldquo;Show Notification&rdquo;</strong> saying &ldquo;Saved to archive&rdquo; so you get visible confirmation.</li>
  <li>Use it: in Safari, tap <strong>Share &rarr; Save to CFO Library</strong>. The article lands in the queue-free save path, same as the bookmarklet.</li>
</ol>
<p style="margin:0;color:var(--muted);font-size:13px;">Articles saved this way arrive untagged&mdash;tag them later in the Library, or add a second JSON text field named <code>tags</code> with a comma-separated list if you want a fixed default.</p>
</div>
</details>

<div style="font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin:22px 0 8px;">Saving to Read Later instead</div>
<p style="color:var(--muted);font-size:13.5px;margin:0 0 12px;">Same idea, same no-login token, a second destination: these post to <code>/save-later</code> and land in the Reader's Read Later list instead of the archive&mdash;no enrichment, no tags, just a quick queue for something to read later.</p>

<details style="margin-bottom:12px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 20px;">
<summary style="cursor:pointer;font-family:var(--font-head);font-weight:600;font-size:16px;color:var(--navy);display:flex;align-items:baseline;gap:8px;"><span class="disclosure-caret">&#9654;</span>Desktop&mdash;the bookmarklet</summary>
<div style="font-size:14px;color:var(--ink-soft);line-height:1.7;margin-top:12px;">
<p style="margin:0 0 10px;">Same mechanism as the archive bookmarklet above&mdash;an ordinary browser bookmark whose &ldquo;URL&rdquo; is a tiny program. Clicking it grabs the current page's address (and title) and saves it straight to Read Later&mdash;no prompt, one click.</p>
<ol style="margin:0 0 10px;padding-left:20px;">
  <li>Open <a href="/read-later-bookmarklet">/read-later-bookmarklet</a> (login-gated) and copy the <em>entire</em> snippet&mdash;click the text, <strong>Cmd+A</strong>, <strong>Cmd+C</strong>.</li>
  <li>Show the bookmarks bar (<strong>Cmd+Shift+B</strong> in Chrome), right-click an empty spot on it &rarr; <strong>Add page&hellip;</strong></li>
  <li>Name: <code>Save to Read Later</code>. URL: <strong>paste the snippet</strong>. Save.</li>
  <li>On any article page, click it like a button &rarr; &ldquo;Saved to Read Later.&rdquo; It shows up right away under the Reader's Read Later view.</li>
</ol>
<p style="margin:0;color:var(--muted);font-size:13px;">It won't fire on browser-internal pages (new tab, chrome:// pages)&mdash;that's a browser rule. The snippet contains the save token in plaintext, so don't paste it anywhere public.</p>
</div>
</details>

<details style="margin-bottom:12px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 20px;">
<summary style="cursor:pointer;font-family:var(--font-head);font-weight:600;font-size:16px;color:var(--navy);display:flex;align-items:baseline;gap:8px;"><span class="disclosure-caret">&#9654;</span>iPhone / iPad&mdash;Share-Sheet shortcut</summary>
<div style="font-size:14px;color:var(--ink-soft);line-height:1.7;margin-top:12px;">
<p style="margin:0 0 10px;">One-time setup in the <strong>Shortcuts</strong> app (~5 minutes); afterwards &ldquo;Save to Read Later&rdquo; appears in Safari's share sheet, alongside &ldquo;Save to CFO Library&rdquo; if you set that one up too.</p>
<ol style="margin:0 0 10px;padding-left:20px;">
  <li>Shortcuts app &rarr; <strong>+</strong> to create a new shortcut &rarr; rename it <code>Save to Read Later</code>.</li>
  <li>Tap the shortcut's <strong>info (&#9432;)</strong> panel &rarr; turn on <strong>Show in Share Sheet</strong>. Under the accepted types, keep <strong>URLs</strong> and <strong>Safari web pages</strong>.</li>
  <li>Add action <strong>&ldquo;Get URLs from Input&rdquo;</strong> (its input should be <em>Shortcut Input</em>).</li>
  <li>Add action <strong>&ldquo;Get Contents of URL&rdquo;</strong> and expand its options:
    <ul style="margin:4px 0;padding-left:18px;">
      <li>URL: <code>{_esc(PUBLIC_BASE)}/save-later{'?token=' + _esc(SAVE_TOKEN) if SAVE_TOKEN else ''}</code></li>
      <li>Method: <strong>POST</strong></li>
      <li>Request Body: <strong>JSON</strong> &rarr; add a text field named <code>url</code> whose value is the <em>URLs</em> variable from step 3.</li>
    </ul></li>
  <li>Optional: add a second JSON text field named <code>title</code> (e.g. the <em>Name</em> output of a <strong>&ldquo;Get Details of Safari Web Page&rdquo;</strong> action) so the item shows a real title in the Reader right away, instead of &ldquo;(no title)&rdquo; until you open it.</li>
  <li>Optional: add <strong>&ldquo;Show Notification&rdquo;</strong> saying &ldquo;Saved to Read Later&rdquo; so you get visible confirmation.</li>
  <li>Use it: in Safari, tap <strong>Share &rarr; Save to Read Later</strong>. The article lands straight in the Reader's Read Later list, no queue.</li>
</ol>
<p style="margin:0;color:var(--muted);font-size:13px;">Read Later has no tags concept, so there's no tags field to add here&mdash;unlike the archive shortcut above.</p>
</div>
</details>

<p style="color:var(--muted);font-size:12.5px;line-height:1.6;margin:10px 0 0;">If you ever rotate <code>LINKLIB_SAVE_TOKEN</code> or change <code>LINKLIB_PUBLIC_BASE</code>, all four snippets above stop working at once&mdash;they share the same token, and the old copies embed the old values. Set them up again from the instructions above.</p>"""

    # 5, not the literal 1 card: Manage feeds plus the archive bookmarklet/
    # Share-Sheet accordions and the Read Later bookmarklet/Share-Sheet
    # accordions. See _lib_quadrant's count_override note.
    saving_articles_html = _lib_quadrant("New content", saving_articles_body,
                                         ["/admin/library/feeds"],
                                         count_override=5)

    existing_mgmt_html = _lib_section(
        "Existing archive management",
        ["/admin/library/backfill-content", "/admin/library/dedupe", "/admin/library/review-removals",
         "/admin/library/bulk-delete"],
        "Working with what's already saved.")

    archive_additions_html = _lib_section(
        "Archive additions & backup", ["/admin/library/backup", "/admin/library/queue"],
        "Bringing new content in&mdash;an ongoing feed scan plus an occasional historical sweep, both reviewed on one page before anything's saved&mdash;plus an on-demand snapshot for right before something risky.")

    tag_mgmt_html = _lib_section(
        "Tag management",
        ["/admin/library/tags", "/admin/library/tag-style", "/admin/library/enrich"],
        "How tags get created, taught, and kept tidy&mdash;and the summaries that ride along with them.")

    body = f"""<div class="page page-admin">
<style>
/* Four quadrants on explicitly named grid areas, not auto-placement. Auto-flow
   is what produced the earlier ragged layout — blocks landed wherever content
   length pushed them, and an odd count left a hole. Named areas pin each
   quadrant regardless of how much content it holds. */
/* Two INDEPENDENT flowing columns, not a row-coupled grid. A real 2-row grid
   makes both cells in a row share that row's height, so expanding one quadrant
   pushed the whole next row down in both columns at once. Column independence
   is the deliberate trade-off: row-2 headings ("Tag management" vs "Archive
   additions & backup") are no longer guaranteed to share a Y. */
.lib-cols{{display:flex;gap:28px;align-items:flex-start;}}
.lib-col{{flex:1 1 0;min-width:0;display:flex;flex-direction:column;gap:34px;}}
/* Quadrant boxes come from the shared `_disclosure_group` component (same row
   as the /admin index's sections), so there's no bespoke summary styling here.
   Only the bottom margin is dropped: the flex columns own the vertical rhythm
   via their own gap. */
.lib-quad{{margin-bottom:0 !important;}}
/* The .lib-q-* classes carry no desktop rules — they exist to give the mobile
   query below something to `order`, and to name each quadrant for tests. */
@media (max-width:900px){{
  /* One column. `display:contents` dissolves the two column wrappers so all
     four quadrants become direct flex children of .lib-cols, which is what
     lets `order` interleave them across the columns — DOM order is
     new/tags/existing/backup (column order), the required reading order is
     new/existing/tags/backup. */
  /* align-items must be reset here, not just inherited from the desktop rule.
     It governs the CROSS axis, so `flex-start` — correct in row direction,
     where it stops the two columns stretching to a shared height — becomes
     horizontal once this flips to column, shrinking every box to its own
     content width (measured 261/342/306/342px at 390px wide before this).
     `stretch` gives all four the container's full width. */
  .lib-cols{{flex-direction:column;gap:30px;align-items:stretch;}}
  .lib-col{{display:contents;}}
  .lib-q-new{{order:1;}}
  .lib-q-existing{{order:2;}}
  .lib-q-tags{{order:3;}}
  .lib-q-backup{{order:4;}}
}}
</style>
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:4px;flex-wrap:wrap;">
  <h1 style="margin:0;">Library</h1>
  {open_reader_button}
</div>
<p style="color:var(--muted);margin:4px 0 18px;">The tools below cover backing the archive up, bringing in new content, keeping it clean, and readying it for the FP&amp;A Buddy assistant to reason from&mdash;grouped by what they're for, not a fixed order. Jump to whichever you need.</p>
{flow_html}
<div class="lib-cols">
<div class="lib-col">
<div class="lib-q-new">{saving_articles_html}</div>
<div class="lib-q-tags">{tag_mgmt_html}</div>
</div>
<div class="lib-col">
<div class="lib-q-existing">{existing_mgmt_html}</div>
<div class="lib-q-backup">{archive_additions_html}</div>
</div>
</div>
</div>"""
    return HTMLResponse(_page("Library—Admin", "Admin", body, authed=True))


# ---------------------------------------------------------------------------
# Feed management — the RSS subscription list behind the Reader and FP&A Buddy
# ---------------------------------------------------------------------------

def _publish_feeds(lib) -> None:
    """Regenerate preferred_sites.opml from the feeds tables.

    Call after every mutation of feed_sections/feeds. Library.write_opml also
    clears sources.preferred_domains' lru_cache, so this single call covers
    both halves of "make the change visible downstream" — see that method's
    docstring for why those two are deliberately inseparable rather than two
    things each route has to remember.
    """
    lib.write_opml(OPML_PATH)


def _feed_cookie_readout(xml_url: str) -> str:
    """Read-only line showing whether this feed's domain currently has a
    subscriber cookie configured (LINKLIB_COOKIE_<DOMAIN>) — computed live,
    not a stored declaration. Only rendered when a URL is already known (the
    edit form), since the add form has nothing to compute against until
    after the feed is saved. Replaces the old has_paywall_cookie checkbox,
    which recorded that a feed *should* need a cookie but never reflected
    whether one was actually configured — see CLAUDE.md's Feeds-page
    Cookie-checkbox note."""
    from linklib.extract import has_configured_cookie
    domain = (urlsplit(xml_url).netloc or "").lower().split(":")[0]
    if domain.startswith("www."):
        domain = domain[4:]
    if not domain:
        return ""
    configured = has_configured_cookie(domain)
    color = "var(--seafoam-deep)" if configured else "var(--muted)"
    label = "Cookie configured for this domain" if configured else "No cookie configured for this domain"
    return (f'  <div>\n'
            f'    <label style="display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;">Cookie</label>\n'
            f'    <p style="font-size:14px;color:{color};margin:0;">{_esc(label)}</p>\n'
            f'    <p style="font-size:12.5px;color:var(--muted);margin:6px 0 0;line-height:1.5;">Computed live from whether <code>{_esc(_cookie_env_var_name(domain))}</code> is set in the host environment — not something you set here. See the footnote below the table for how to find and set the right cookie.</p>\n'
            f'  </div>\n')


def _cookie_env_var_name(domain: str) -> str:
    from linklib.extract import _cookie_env_var
    return _cookie_env_var(domain)


def _feed_form_fields(sections: list, values: dict) -> str:
    """Shared field markup for the add-feed and edit-feed forms."""
    opts = "".join(
        f'<option value="{s["id"]}"{" selected" if str(values.get("section_id", "")) == str(s["id"]) else ""}>'
        f'{_esc(s["name"])}</option>'
        for s in sections
    )
    inp = ("width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;"
           "font:inherit;font-size:15px;background:#fff;box-sizing:border-box;")
    lab = "display:block;font-size:14px;font-weight:500;color:var(--navy);margin-bottom:6px;"
    hint = "font-size:12.5px;color:var(--muted);margin:6px 0 0;line-height:1.5;"
    exclude_checked = " checked" if values.get("exclude_from_queue") else ""
    sub_checked = " checked" if values.get("has_active_subscription") else ""
    cookie_readout = _feed_cookie_readout(values.get("xml_url", ""))
    return f"""  <div>
    <label style="{lab}">Feed URL *</label>
    <input type="url" name="xml_url" required value="{_esc(values.get('xml_url', ''))}"
      placeholder="https://example.com/feed/" style="{inp}">
    <p style="{hint}">The RSS or Atom address, not the site's homepage. It's checked before saving, so a wrong address is rejected here rather than sitting in the list producing nothing. Stored exactly as entered: if a paid subscription gives you a feed URL with a token in it, paste the whole thing and nothing will trim it.</p>
  </div>
  <div>
    <label style="{lab}">Name *</label>
    <input type="text" name="name" required maxlength="120" value="{_esc(values.get('name', ''))}"
      placeholder="e.g. Mostly Metrics (CJ Gustafson)" style="{inp}">
    <p style="{hint}">How the source is labelled in the Reader. Leave blank to use the feed's own title.</p>
  </div>
  <div>
    <label style="{lab}">Section *</label>
    <select name="section_id" required style="{inp}">{opts}</select>
  </div>
  <div>
    <label style="{lab}">Site URL <span style="font-weight:400;color:var(--muted);">(optional)</span></label>
    <input type="url" name="html_url" value="{_esc(values.get('html_url', ''))}"
      placeholder="https://example.com/" style="{inp}">
    <p style="{hint}">The publication's own address. This is the one FP&amp;A Buddy's web search is restricted to, and the one the historical sweep crawls for back catalog. Left blank, it's taken from the feed itself.</p>
  </div>
  <div>
    <label style="display:flex;align-items:center;gap:8px;font-size:14px;color:var(--ink-soft);">
      <input type="checkbox" name="exclude_from_queue" value="1"{exclude_checked}>
      Read only
    </label>
    <p style="{hint}">Read it in the Reader, but never propose it into the archive queue. Set per feed, so one source in a section can be read-only without affecting the rest.</p>
  </div>
{cookie_readout}  <div>
    <label style="display:flex;align-items:center;gap:8px;font-size:14px;color:var(--ink-soft);">
      <input type="checkbox" name="has_active_subscription" value="1"{sub_checked}>
      Subscriber
    </label>
    <p style="{hint}">Whether you currently pay for this source, as a note to yourself. It doesn't affect fetching. Nothing in the app reads this: it doesn't gate anything, doesn't reach the Reader, and is separate from the paywall cookie above.</p>
  </div>"""


@app.get("/admin/library/feeds", response_class=HTMLResponse)
def admin_feeds(request: Request, background_tasks: BackgroundTasks,
                msg: str = "", error: str = ""):
    if not _is_authed(request):
        return _login_redirect(request)
    auth_button, auth_panel = _auth_cookie_controls(request, background_tasks)
    lib = _lib()
    try:
        sections = lib.list_feed_sections()
        feeds = lib.list_feeds()
        section_counts = {s["id"]: lib.count_feeds_in_section(s["id"]) for s in sections}
    finally:
        lib.close()

    banner = (f'<p style="background:#d1fae5;color:#065f46;border-radius:10px;padding:10px 16px;'
              f'font-size:14px;margin:-6px 0 16px;">{_esc(msg)}</p>' if msg else '')
    error_banner = (f'<p style="background:var(--coral-wash);color:var(--navy);border-radius:10px;'
                    f'padding:10px 16px;font-size:14px;margin:-6px 0 16px;">{_esc(error)}</p>'
                    if error else '')

    # -- one flat feed table -------------------------------------------------
    # Section is a per-row dropdown and read-only a per-row checkbox, both
    # posting on change, so a feed's grouping and its queue eligibility are
    # edited in place rather than through a section-level control.
    from linklib.extract import has_configured_cookie
    feed_rows = ""
    for f in feeds:
        opts = "".join(
            f'<option value="{s["id"]}"{" selected" if s["id"] == f["section_id"] else ""}>'
            f'{_esc(s["name"])}</option>' for s in sections)
        _cookie_domain = (urlsplit(f["xml_url"]).netloc or "").lower().split(":")[0]
        if _cookie_domain.startswith("www."):
            _cookie_domain = _cookie_domain[4:]
        _cookie_configured = bool(_cookie_domain) and has_configured_cookie(_cookie_domain)
        feed_rows += f"""<tr class="ff-row">
  <td class="ff-name">{_esc(f['name'])}</td>
  <td class="ff-url"><a href="{_esc(f['xml_url'])}" target="_blank" rel="noopener">{_esc(f['xml_url'])}</a></td>
  <td class="ff-section">
    <form method="post" action="/admin/library/feeds/{f['id']}/section" style="margin:0;">
      <select name="section_id" onchange="this.form.submit()" aria-label="Section for {_esc(f['name'])}"
        style="width:100%;padding:5px 8px;border:1px solid var(--line);border-radius:7px;font:inherit;font-size:13px;background:#fff;">{opts}</select>
    </form>
  </td>
  <td class="ff-readonly">
    <form method="post" action="/admin/library/feeds/{f['id']}/read-only" style="margin:0;">
      <input type="checkbox" name="exclude_from_queue" value="1" onchange="this.form.submit()"
        aria-label="Read only: {_esc(f['name'])}"{' checked' if f['exclude_from_queue'] else ''}>
    </form>
  </td>
  <td class="ff-cookie">
    <span aria-label="Cookie for {_esc(f['name'])}: {'configured' if _cookie_configured else 'not configured'}"
      title="Computed from whether a subscriber cookie is configured for this domain — not editable here."
      style="color:{'var(--seafoam-deep)' if _cookie_configured else 'var(--muted)'};font-size:13px;">
      {'&#10003; configured' if _cookie_configured else '&mdash;'}
    </span>
  </td>
  <td class="ff-sub">
    <form method="post" action="/admin/library/feeds/{f['id']}/subscription" style="margin:0;">
      <input type="checkbox" name="has_active_subscription" value="1" onchange="this.form.submit()"
        aria-label="Subscriber: {_esc(f['name'])}"{' checked' if f['has_active_subscription'] else ''}>
    </form>
  </td>
  <td class="ff-actions">
    <a href="/admin/library/feeds/{f['id']}/edit" class="btn btn-ghost" style="font-size:12px;padding:5px 12px;">Edit</a>
    <form method="post" action="/admin/library/feeds/{f['id']}/delete" style="display:inline;margin:0 0 0 4px;"
          onsubmit="return confirm('Remove &quot;{_esc(f['name'])}&quot; from your feeds? Articles already saved from it stay in the archive.');">
      <button type="submit" class="btn btn-ghost" style="font-size:12px;padding:5px 12px;color:#b91c1c;border-color:#fca5a5;">Remove</button>
    </form>
  </td>
</tr>"""
    if not feeds:
        feed_rows = ('<tr class="ff-row"><td colspan="7" class="ff-empty">'
                     'No feeds yet. Add a section below, then add a feed to it.</td></tr>')

    # -- manage sections: a table matching the feed table above --------------
    # The rename form lives in the Section cell while its submit button sits in
    # Actions, associated by the `form` attribute rather than nesting a form
    # across cells (invalid HTML). Same plain-HTML trick /admin/tools/software/categories
    # already uses for exactly this two-column split — no JS.
    section_rows = ""
    for s in sections:
        n = section_counts.get(s["id"], 0)
        form_id = f"sec-rename-{s['id']}"
        if n:
            # Only an empty section can be removed, so the button is disabled
            # rather than absent: an absent control reads as "you can't remove
            # sections at all", a disabled one reads as "not this one, yet".
            remove = (
                f'<button type="button" class="btn btn-ghost fs-remove-off" disabled '
                f'title="Only an empty section can be removed. Move its {n} '
                f'feed{"s" if n != 1 else ""} to another section first.">Remove</button>')
        else:
            remove = (
                f'<form method="post" action="/admin/library/feeds/sections/{s["id"]}/delete" '
                f'style="display:inline;margin:0 0 0 4px;" '
                f'onsubmit="return confirm(\'Remove the empty section &quot;{_esc(s["name"])}&quot;?\');">'
                f'<button type="submit" class="btn btn-ghost fs-remove">Remove</button></form>')
        section_rows += f"""<tr class="fs-row">
  <td class="fs-name">
    <form id="{form_id}" method="post" action="/admin/library/feeds/sections/{s['id']}/rename" style="margin:0;">
      <input type="text" name="name" value="{_esc(s['name'])}" required maxlength="80"
        aria-label="Section name" style="width:100%;box-sizing:border-box;padding:6px 10px;border:1px solid var(--line);border-radius:7px;font:inherit;font-size:13.5px;background:#fff;">
    </form>
  </td>
  <td class="fs-count">{n} feed{'s' if n != 1 else ''}</td>
  <td class="fs-actions">
    <button type="submit" form="{form_id}" class="btn btn-ghost" style="font-size:12px;padding:5px 12px;">Rename</button>
    {remove}
  </td>
</tr>"""
    if not sections:
        section_rows = ('<tr class="fs-row"><td colspan="3" class="ff-empty">'
                        'No sections yet.</td></tr>')

    body = f"""<div class="page page-admin">
<style>
/* Cookie health summary. Sits under the header actions, deliberately not in
   the feed table: cookies are keyed by domain while the table is keyed by
   feed, so a per-row light would misrepresent the relationship the moment two
   feeds shared a domain. A dot, never a checkbox — the Cookie column declares
   that a feed needs a cookie; this reports whether that cookie still works. */
.ck-panel{{background:var(--surface);border:1px solid var(--line);border-radius:12px;
  padding:10px 14px;margin:0 0 18px;display:grid;gap:4px;}}
.ck-row{{display:flex;align-items:baseline;gap:9px;font-size:13px;flex-wrap:wrap;}}
.ck-dot{{width:9px;height:9px;border-radius:50%;flex:0 0 auto;
  transform:translateY(-1px);}}
.ck-dom{{font-weight:600;color:var(--ink-soft);}}
/* Deliberately NOT tinted to match its dot. #CA8A04 as text on --surface is
   2.94:1, failing AA (4.5) and even AA-large (3.0); the colour lives on the
   dot, which is a graphic, while the word stays in normal readable ink. */
.ck-state{{font-weight:600;color:var(--ink-soft);}}
.ck-detail{{color:var(--muted);min-width:0;overflow-wrap:anywhere;}}
.ck-age{{color:var(--muted);margin-left:auto;white-space:nowrap;}}
@media (max-width:560px){{
  /* Let the timestamp sit with the text rather than stranded at the far edge
     of a wrapped row, where it reads as belonging to the next line. */
  .ck-age{{margin-left:0;}}
}}
.ff-head{{display:flex;align-items:center;justify-content:space-between;gap:12px;
  margin-bottom:4px;flex-wrap:wrap;}}
/* Both actions in one group so they wrap together under the title rather than
   the primary button stranding on a line of its own. */
.ff-head-actions{{display:flex;align-items:center;gap:10px;flex-wrap:wrap;}}
.ff-head-actions form{{margin:0;}}
@media (max-width:560px){{
  /* Too narrow for title-plus-two-buttons: let the group take the full width
     and sit under the H1, secondary first so the primary stays rightmost. */
  .ff-head-actions{{width:100%;justify-content:flex-start;}}
}}
.ff-table,.fs-table{{width:100%;border-collapse:collapse;table-layout:fixed;}}
.ff-row>td,.fs-row>td{{padding:9px 12px;vertical-align:middle;border-top:1px solid var(--line);}}
.ff-table thead th,.fs-table thead th{{padding:9px 12px;text-align:left;font-size:12px;color:var(--muted);
  font-weight:600;text-transform:uppercase;letter-spacing:.06em;background:var(--bg);}}
.ff-table tbody tr:first-child>td,.fs-table tbody tr:first-child>td{{border-top:0;}}
.ff-name{{font-weight:600;font-size:14px;width:18%;}}
.ff-url{{font-size:13px;color:var(--muted);width:23%;}}
.ff-url a{{word-break:break-all;}}
.ff-section{{width:14%;}}
.ff-readonly{{width:8%;text-align:center;}}
.ff-cookie{{width:10%;text-align:center;}}
.ff-sub{{width:10%;text-align:center;}}
.ff-actions{{width:17%;text-align:right;white-space:nowrap;}}
.ff-empty{{padding:16px 12px;color:var(--muted);font-size:13.5px;}}
/* Sections table — same shape as the feed table, three columns. */
.fs-name{{width:50%;}}
.fs-count{{width:18%;font-size:13px;color:var(--muted);}}
.fs-actions{{width:32%;text-align:right;white-space:nowrap;}}
.fs-remove{{font-size:12px;padding:5px 12px;color:#b91c1c;border-color:#fca5a5;}}
/* Disabled rather than absent: an absent control reads as "sections can't be
   removed at all", a disabled one reads as "not this one, yet". The title
   attribute carries the reason on desktop; the Feeds count carries it
   everywhere, including touch, where there's no hover. */
.fs-remove-off{{font-size:12px;padding:5px 12px;color:var(--muted);border-color:var(--line);
  opacity:.55;cursor:not-allowed;margin-left:4px;}}
/* Below this width five columns can't coexist: the URL cell gets narrow enough
   that word-break:break-all wraps a feed address one character per line, which
   turned a single row several hundred pixels tall on a phone. Stacking the
   cells gives each one the full width, with a label so the section dropdown
   and the read-only box are still identifiable out of table context. */
@media (max-width:820px){{
  .ff-table,.ff-table tbody,.ff-row,.ff-row>td,
  .fs-table,.fs-table tbody,.fs-row,.fs-row>td{{display:block;width:auto;}}
  .ff-table thead,.fs-table thead{{display:none;}}
  .ff-row,.fs-row{{border-top:1px solid var(--line);padding:10px 0;}}
  .ff-table tbody tr:first-child,.fs-table tbody tr:first-child{{border-top:0;}}
  .ff-row>td,.fs-row>td{{border-top:0;padding:3px 12px;}}
  .ff-readonly,.ff-cookie,.ff-sub,.ff-actions,.fs-actions{{text-align:left;}}
  .ff-section::before{{content:"Section";display:block;font-size:11.5px;color:var(--muted);
    text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px;}}
  .ff-readonly::before{{content:"Read only";display:block;font-size:11.5px;color:var(--muted);
    text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px;}}
  /* Always labelled, unlike the cookie cell: this is a checkbox that carries
     meaning in both states, so an unchecked box still needs its label. */
  .ff-sub::before{{content:"Subscriber";display:block;font-size:11.5px;color:var(--muted);
    text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px;}}
  /* Labelled unconditionally, same as Subscriber. Holds a computed
     configured/not-configured readout that carries meaning in both states
     (see _feed_cookie_readout), so it can't be hidden when "not configured". */
  .ff-cookie::before{{content:"Cookie";display:block;font-size:11.5px;color:var(--muted);
    text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px;}}
}}
</style>
<p style="margin:0 0 4px;"><a href="/admin/library" style="font-size:13px;color:var(--muted);">&larr; Library</a></p>
<div class="ff-head">
  <h1 style="margin:0;">Feeds</h1>
  <div class="ff-head-actions">
    {auth_button}
    <a href="/admin/library/feeds/new" class="btn" style="font-size:14px;padding:8px 18px;">+ Add feed</a>
  </div>
</div>
{auth_panel}
<p style="color:var(--muted);margin:8px 0 6px;">The RSS subscriptions behind the Reader's Feed view. This same list is the domain allowlist FP&amp;A Buddy's web search is restricted to, so a source added here becomes citable there too. Changes take effect on the next page load, with no restart or deploy needed.</p>
<ul style="color:var(--muted);margin:0 0 18px;padding-left:20px;font-size:14px;line-height:1.7;">
<li>The Reader's <strong>Sources</strong> rail only lists feeds that currently have items in view, so a quiet or unreachable feed can appear here and not there. That's expected rather than a sync problem.</li>
<li><strong>Read only</strong> feeds stay live in the Reader but are never proposed into the <a href="/admin/library/queue">archive queue</a>. It's set per feed, so one source in a section can be read-only without affecting the rest.</li>
<li><strong>Cookie</strong> shows whether this feed's domain currently has a subscriber cookie configured &mdash; computed live from the host environment, not something you set here. Each domain's cookie lives in its own <code>LINKLIB_COOKIE_&lt;DOMAIN&gt;</code> variable, and <code>extract.fetch_page</code> applies it automatically wherever the domain matches (see <code>RUNBOOK.md</code> &sect;5 for finding and setting one). <strong>No cookie value is ever stored in this database</strong> &mdash; only the domain names checked are baked into the code.</li>
<li><strong>Subscriber</strong> marks whether you currently pay for a source, as a note to yourself. Nothing reads it&mdash;it doesn't gate fetching, doesn't reach the Reader, and is separate from the cookie above. A source can be paywalled without you subscribing to it, which is the distinction this records.</li>
</ul>
{banner}{error_banner}
<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden;">
  <table class="ff-table">
    <thead><tr>
      <th style="width:18%;">Name</th><th style="width:23%;">URL</th>
      <th style="width:14%;">Section</th>
      <th style="width:8%;text-align:center;">Read only</th>
      <th style="width:10%;text-align:center;">Cookie</th>
      <th style="width:10%;text-align:center;">Subscriber</th>
      <th style="width:17%;text-align:right;">Actions</th>
    </tr></thead>
    <tbody>{feed_rows}</tbody>
  </table>
</div>
<p style="font-size:12.5px;color:var(--muted);margin:10px 0 0;line-height:1.6;">
<strong>Finding the right cookie in DevTools:</strong> log into the site, open DevTools &rarr; <strong>Application</strong> &rarr; <strong>Cookies</strong> for that domain, and copy the minimum cookie that carries the session &mdash; not the whole jar. It varies by platform: a <strong>Substack</strong> site's session cookie is typically named <code>connect.sid</code>; a <strong>beehiiv</strong> site (e.g. Mostly Metrics) uses a signed JWT, usually under a name containing <code>token</code> or <code>session</code>. When in doubt, RUNBOOK.md &sect;5.2's fallback still works: copy the entire <code>Cookie:</code> request header instead of hunting for one name.
</p>

<h2 style="font-size:17px;margin:34px 0 4px;">Manage sections</h2>
<p style="color:var(--muted);font-size:13.5px;margin:0 0 12px;">Sections group feeds in the Reader's Sources rail. They carry no settings of their own: whether a source reaches the archive queue is set per feed in the table above. A section can only be removed once it's empty.</p>
<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden;max-width:680px;">
  <table class="fs-table">
    <thead><tr>
      <th style="width:50%;">Section</th><th style="width:18%;">Feeds</th>
      <th style="width:32%;text-align:right;">Actions</th>
    </tr></thead>
    <tbody>{section_rows}</tbody>
  </table>
</div>
<form method="post" action="/admin/library/feeds/sections/new"
      style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:16px 0 0;">
  <input type="text" name="name" required maxlength="80" placeholder="New section name"
    style="padding:8px 12px;border:1px solid var(--line);border-radius:9px;font:inherit;font-size:14px;background:#fff;">
  <button type="submit" class="btn btn-ghost" style="font-size:13px;padding:6px 14px;">+ Add section</button>
</form>
</div>"""
    return HTMLResponse(_page("Feeds—Library Admin", "Admin", body, authed=True))


@app.post("/admin/library/feeds/sections/new")
async def admin_feeds_section_new(request: Request):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    name = (form.get("name") or "").strip()
    if not name:
        return RedirectResponse(
            f"/admin/library/feeds?error={quote('Give the section a name.')}", status_code=303)
    lib = _lib()
    try:
        if any(s["name"].lower() == name.lower() for s in lib.list_feed_sections()):
            return RedirectResponse(
                f"/admin/library/feeds?error={quote(f'A section called {name} already exists.')}",
                status_code=303)
        lib.add_feed_section(name)
        _publish_feeds(lib)
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(f'Added the {name} section.')}",
                            status_code=303)


@app.post("/admin/library/feeds/sections/{section_id}/rename")
async def admin_feeds_section_rename(request: Request, section_id: int):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    name = (form.get("name") or "").strip()
    if not name:
        return RedirectResponse(
            f"/admin/library/feeds?error={quote('A section needs a name.')}", status_code=303)
    lib = _lib()
    try:
        if not lib.get_feed_section(section_id):
            raise HTTPException(status_code=404, detail="section not found")
        clash = [s for s in lib.list_feed_sections()
                 if s["name"].lower() == name.lower() and s["id"] != section_id]
        if clash:
            return RedirectResponse(
                f"/admin/library/feeds?error={quote(f'A section called {name} already exists.')}",
                status_code=303)
        lib.rename_feed_section(section_id, name)
        _publish_feeds(lib)
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(f'Renamed the section to {name}.')}",
                            status_code=303)


@app.post("/admin/library/feeds/sections/{section_id}/delete")
def admin_feeds_section_delete(request: Request, section_id: int):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        section = lib.get_feed_section(section_id)
        if not section:
            raise HTTPException(status_code=404, detail="section not found")
        name = section["name"]
        remaining = lib.count_feeds_in_section(section_id)
        if remaining:
            # Also enforced in delete_feed_section; checked here so the admin
            # gets the count rather than a 500.
            plural = "s" if remaining != 1 else ""
            detail = (f"{name} still has {remaining} feed{plural}. "
                      f"Move them to another section first.")
            return RedirectResponse(f"/admin/library/feeds?error={quote(detail)}",
                                    status_code=303)
        lib.delete_feed_section(section_id)
        _publish_feeds(lib)
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(f'Removed the {name} section.')}",
                            status_code=303)


@app.post("/admin/library/feeds/{feed_id}/section")
async def admin_feeds_set_section(request: Request, feed_id: int):
    """Move a feed to another section, from the table's per-row dropdown.

    Deliberately narrow: it touches section_id only and never re-writes
    xml_url, so a feed whose URL carries a subscriber token can be regrouped
    with no chance of the URL being rewritten in passing.
    """
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    raw = (form.get("section_id") or "").strip()
    lib = _lib()
    try:
        feed = lib.get_feed(feed_id)
        if not feed:
            raise HTTPException(status_code=404, detail="feed not found")
        if not raw.isdigit() or not lib.get_feed_section(int(raw)):
            return RedirectResponse(
                f"/admin/library/feeds?error={quote('Pick an existing section.')}",
                status_code=303)
        section = lib.get_feed_section(int(raw))
        lib.move_feed_to_section(feed_id, int(raw))
        _publish_feeds(lib)
        detail = f"Moved {feed['name']} to {section['name']}."
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(detail)}", status_code=303)


@app.post("/admin/library/feeds/{feed_id}/read-only")
async def admin_feeds_set_read_only(request: Request, feed_id: int):
    """Toggle a feed's archive-queue eligibility from the table's checkbox.

    Same narrowness as the section route: exclude_from_queue only, never the
    URL. An unchecked box posts no field at all, which is the off state.
    """
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    excluded = bool(form.get("exclude_from_queue"))
    lib = _lib()
    try:
        feed = lib.get_feed(feed_id)
        if not feed:
            raise HTTPException(status_code=404, detail="feed not found")
        lib.set_feed_excluded(feed_id, excluded)
        # No OPML rewrite: the file has no field for this flag, and the queue
        # reads it straight from the DB. Regenerating here would be a no-op
        # write that only churns the file's mtime.
        state = "read only" if excluded else "eligible for the archive queue"
        detail = f"{feed['name']} is now {state}."
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(detail)}", status_code=303)



@app.post("/admin/library/feeds/{feed_id}/subscription")
async def admin_feeds_set_subscription(request: Request, feed_id: int):
    """Toggle the informational subscription flag from the table's checkbox.

    Same narrowness as the read-only route: one column, never the URL. An
    unchecked box posts no field at all, which is the off state.

    Nothing downstream reads this flag, so there's deliberately no OPML
    rewrite, no cache clear, and no other side effect — it's a note to self.
    """
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    active = bool(form.get("has_active_subscription"))
    lib = _lib()
    try:
        feed = lib.get_feed(feed_id)
        if not feed:
            raise HTTPException(status_code=404, detail="feed not found")
        lib.set_feed_active_subscription(feed_id, active)
        state = "marked as an active subscription" if active else "no longer marked as subscribed"
        detail = f"{feed['name']} is {state}."
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(detail)}", status_code=303)


@app.get("/admin/library/feeds/new", response_class=HTMLResponse)
def admin_feeds_new(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        sections = lib.list_feed_sections()
    finally:
        lib.close()
    if not sections:
        return RedirectResponse(
            f"/admin/library/feeds?error={quote('Add a section first, then add feeds to it.')}",
            status_code=303)
    return HTMLResponse(_page("Add a feed—Library Admin", "Admin",
                              _feed_form_page("Add a feed", "/admin/library/feeds/new",
                                              sections, {}, "", "Add feed"),
                              authed=True))


def _feed_form_page(heading: str, action: str, sections: list, values: dict,
                    error: str, submit_label: str) -> str:
    error_html = (f'<p style="background:var(--coral-wash);color:var(--navy);border-radius:10px;'
                  f'padding:12px 16px;font-size:14px;margin:0 0 18px;line-height:1.55;">{_esc(error)}</p>'
                  if error else '')
    return f"""<div class="page page-form">
<p style="margin:0 0 4px;"><a href="/admin/library/feeds" style="font-size:13px;color:var(--muted);">&larr; Feeds</a></p>
<h1>{_esc(heading)}</h1>
{error_html}
<form method="post" action="{action}" style="display:grid;gap:20px;">
{_feed_form_fields(sections, values)}
  <div>
    <button type="submit" class="btn">{_esc(submit_label)}</button>
    <a href="/admin/library/feeds" class="btn btn-ghost" style="margin-left:10px;">Cancel</a>
  </div>
</form>
</div>"""


@app.post("/admin/library/feeds/new")
async def admin_feeds_new_submit(request: Request):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    values = {
        "name": (form.get("name") or "").strip(),
        # .strip() removes surrounding whitespace only. The URL is otherwise
        # stored byte for byte — no normalization, no query-string handling —
        # because a feed URL can carry a subscriber token.
        "xml_url": (form.get("xml_url") or "").strip(),
        "html_url": (form.get("html_url") or "").strip(),
        "section_id": (form.get("section_id") or "").strip(),
        "exclude_from_queue": bool(form.get("exclude_from_queue")),
        # Informational only — nothing reads it.
        "has_active_subscription": bool(form.get("has_active_subscription")),
    }
    lib = _lib()
    try:
        sections = lib.list_feed_sections()

        def _reject(message: str):
            return HTMLResponse(_page(
                "Add a feed—Library Admin", "Admin",
                _feed_form_page("Add a feed", "/admin/library/feeds/new",
                                sections, values, message, "Add feed"),
                authed=True), status_code=400)

        if not values["section_id"].isdigit() or not lib.get_feed_section(int(values["section_id"])):
            return _reject("Pick a section for this feed.")
        if lib.find_feed_by_url(values["xml_url"]):
            return _reject("That feed URL is already in your list.")

        from linklib.feed import probe_feed
        probe = probe_feed(values["xml_url"])
        if not probe.ok:
            return _reject(probe.error)

        name = values["name"] or probe.title or values["xml_url"]
        html_url = values["html_url"] or probe.html_url
        # has_paywall_cookie is no longer admin-settable — it's a frozen,
        # unread historical column (see CLAUDE.md's Feeds-page Cookie
        # indicator note), so every new feed just takes the column default.
        lib.add_feed(int(values["section_id"]), name, values["xml_url"], html_url,
                     exclude_from_queue=values["exclude_from_queue"],
                     has_active_subscription=values["has_active_subscription"])
        _publish_feeds(lib)
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(f'Added {name}.')}", status_code=303)


@app.get("/admin/library/feeds/{feed_id}/edit", response_class=HTMLResponse)
def admin_feeds_edit(request: Request, feed_id: int):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        feed = lib.get_feed(feed_id)
        sections = lib.list_feed_sections()
    finally:
        lib.close()
    if not feed:
        raise HTTPException(status_code=404, detail="feed not found")
    values = {"name": feed["name"], "xml_url": feed["xml_url"],
              "html_url": feed["html_url"], "section_id": feed["section_id"],
              "exclude_from_queue": bool(feed["exclude_from_queue"]),
              # Round-tripped so a save that doesn't touch this field can't
              # clear it — update_feed writes it on every call.
              "has_active_subscription": bool(feed["has_active_subscription"])}
    return HTMLResponse(_page("Edit feed—Library Admin", "Admin",
                              _feed_form_page(f'Edit {feed["name"]}',
                                              f"/admin/library/feeds/{feed_id}/edit",
                                              sections, values, "", "Save feed"),
                              authed=True))


@app.post("/admin/library/feeds/{feed_id}/edit")
async def admin_feeds_edit_submit(request: Request, feed_id: int):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    values = {
        "name": (form.get("name") or "").strip(),
        # Verbatim apart from surrounding whitespace — see the add route.
        "xml_url": (form.get("xml_url") or "").strip(),
        "html_url": (form.get("html_url") or "").strip(),
        "section_id": (form.get("section_id") or "").strip(),
        "exclude_from_queue": bool(form.get("exclude_from_queue")),
        # Informational only — see the add route.
        "has_active_subscription": bool(form.get("has_active_subscription")),
    }
    lib = _lib()
    try:
        feed = lib.get_feed(feed_id)
        if not feed:
            raise HTTPException(status_code=404, detail="feed not found")
        sections = lib.list_feed_sections()

        def _reject(message: str):
            return HTMLResponse(_page(
                "Edit feed—Library Admin", "Admin",
                _feed_form_page(f'Edit {feed["name"]}',
                                f"/admin/library/feeds/{feed_id}/edit",
                                sections, values, message, "Save feed"),
                authed=True), status_code=400)

        if not values["section_id"].isdigit() or not lib.get_feed_section(int(values["section_id"])):
            return _reject("Pick a section for this feed.")
        if not values["name"]:
            return _reject("Give this feed a name.")

        url_changed = values["xml_url"] != feed["xml_url"]
        html_url = values["html_url"]
        if url_changed:
            existing = lib.find_feed_by_url(values["xml_url"])
            if existing and existing["id"] != feed_id:
                return _reject("Another feed in your list already uses that URL.")
            # Only re-probe when the URL actually changed: a rename or a section
            # move shouldn't fail because the source happens to be down today.
            from linklib.feed import probe_feed
            probe = probe_feed(values["xml_url"])
            if not probe.ok:
                return _reject(probe.error)
            html_url = values["html_url"] or probe.html_url

        # has_paywall_cookie is no longer admin-settable (see the add-route
        # comment) — preserve the row's existing value rather than letting
        # update_feed's default overwrite it with False on every save.
        lib.update_feed(feed_id, int(values["section_id"]), values["name"],
                        values["xml_url"], html_url,
                        exclude_from_queue=values["exclude_from_queue"],
                        has_paywall_cookie=bool(feed["has_paywall_cookie"]),
                        has_active_subscription=values["has_active_subscription"])
        _publish_feeds(lib)
        saved_name = values["name"]
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(f'Saved {saved_name}.')}",
                            status_code=303)


@app.post("/admin/library/feeds/{feed_id}/delete")
def admin_feeds_delete(request: Request, feed_id: int):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        feed = lib.get_feed(feed_id)
        if not feed:
            raise HTTPException(status_code=404, detail="feed not found")
        name = feed["name"]
        lib.delete_feed(feed_id)
        _publish_feeds(lib)
    finally:
        lib.close()
    return RedirectResponse(f"/admin/library/feeds?msg={quote(f'Removed {name}.')}",
                            status_code=303)


def _auth_recheck_background() -> None:
    """Probe the configured auth cookies and store their health. Runs off-request."""
    lib = _lib()
    try:
        from linklib import authcheck
        authcheck.check_auth_cookies(lib, OPML_PATH)
    except Exception:
        pass
    finally:
        lib.close()


@app.post("/admin/auth/recheck")
def admin_auth_recheck(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        from linklib import authcheck
        authcheck.check_auth_cookies(lib, OPML_PATH)
    finally:
        lib.close()
    # Redirects to Feeds, where the control now lives. The PATH is deliberately
    # unchanged: the Reader's own subscriber-access banner posts here too (see
    # the fetch() in the reader shell), and /admin/auth/recheck isn't
    # library-page-specific, so moving it under /admin/library/feeds/... would
    # make that second caller read oddly for no gain.
    return RedirectResponse("/admin/library/feeds", status_code=303)


# ---------------------------------------------------------------------------
# Archive Queue — staging area for proposed saves
# ---------------------------------------------------------------------------

def _scan_feed_background() -> None:
    """Pull current feed items into the queue (enriched). Runs off-request."""
    lib = _lib()
    try:
        from linklib.queue import scan_feed_into_queue
        scan_feed_into_queue(lib, OPML_PATH)
        backup.maybe_backup(DB_PATH)
    except Exception:
        pass
    finally:
        lib.close()


def _embed_article_background(article_id: int) -> None:
    """Best-effort embed-on-save for one promoted queue article (#93).
    Off-request, mirroring the other _*_background jobs here: promotion
    already returned to the admin before this runs, so a slow or failed
    embedding call never delays the response — the article stays fully
    searchable via FTS5 either way."""
    lib = _lib()
    try:
        from linklib.pipeline import embed_article
        embed_article(lib, article_id)
    except Exception:
        pass
    finally:
        lib.close()


def _redate_background(source: str) -> None:
    """Re-read true publish dates from article pages for a source. Off-request."""
    lib = _lib()
    try:
        from linklib.queue import redate_from_article_pages
        redate_from_article_pages(lib, source)
        backup.maybe_backup(DB_PATH)
    except Exception:
        pass
    finally:
        lib.close()


def _suggest_background(source: str) -> None:
    """Predict keep/skip for a source's pending queue from past picks. Off-request.
    Records a status so the queue page can show what happened (no silent no-ops)."""
    import json as _json
    from datetime import datetime, timezone
    lib = _lib()
    try:
        from linklib.suggest import suggest_approvals
        preds = suggest_approvals(lib, source)
        now = datetime.now(timezone.utc).isoformat()
        if preds is None:
            note = (f"Couldn’t predict {source}. Approve a few articles first so it has "
                    f"something to learn from—or the AI may be briefly unavailable.")
            n = 0
        elif not preds:
            note = f"No pending candidates for {source}."
            n = 0
        else:
            existing = _json.loads(lib.get_setting("queue_suggestions") or "{}")
            existing.update(preds)
            lib.set_setting("queue_suggestions", _json.dumps(existing))
            n = len(preds)
            note = f"Predicted {n} {source} candidate{'s' if n != 1 else ''} from your past picks."
        lib.set_setting("queue_suggest_status",
                        _json.dumps({"source": source, "n": n, "note": note, "at": now}))
    except Exception as exc:
        try:
            from datetime import datetime, timezone
            lib.set_setting("queue_suggest_status", _json.dumps(
                {"source": source, "n": 0, "note": f"Prediction failed: {exc}",
                 "at": datetime.now(timezone.utc).isoformat()}))
        except Exception:
            pass
    finally:
        lib.close()


@app.get("/admin/library/queue", response_class=HTMLResponse)
def admin_queue(request: Request, scanning: int = 0, redating: int = 0, suggesting: int = 0):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        pending = lib.list_queue(status="pending")
        dismissed_n = lib.queue_count(status="dismissed")
        last_saved = lib.last_saved_at()
        import json as _json
        suggestions = _json.loads(lib.get_setting("queue_suggestions") or "{}")
        suggest_status = _json.loads(lib.get_setting("queue_suggest_status") or "{}")
    finally:
        lib.close()

    # Group by source so you can approve a whole publication at once.
    groups: dict[str, list[dict]] = {}
    for c in pending:
        groups.setdefault(c.get("source") or "Other", []).append(c)

    def _short_model(m: str) -> str:
        # claude-opus-4-8 -> opus; claude-haiku-4-5-20251001 -> haiku
        parts = (m or "").split("-")
        return parts[1] if len(parts) > 1 and parts[0] == "claude" else (m or "")

    def _badge(c: dict) -> str:
        if c.get("enriched"):
            label = "enriched"
            sm = _short_model(c.get("enrich_model") or "")
            if sm:
                label = f"enriched &middot; {_esc(sm)}"
            return ('<span style="font-size:11px;font-weight:600;padding:2px 8px;border-radius:20px;'
                    f'background:var(--seafoam-wash);color:var(--seafoam-deep);">{label}</span>')
        return ('<span style="font-size:11px;font-weight:600;padding:2px 8px;border-radius:20px;'
                'background:var(--surface-2);color:var(--muted);">needs enrichment</span>')

    def _card(c: dict) -> str:
        url = _esc(c["url"])
        title = _esc(c.get("title") or c["url"])
        date = _esc((c.get("published_at") or "")[:10])
        summary = _esc((c.get("summary") or "")[:340])
        tags_list = c.get("suggested_tags") or []
        tags_val = _esc(", ".join(tags_list))
        chips = "".join(
            f'<span style="font-size:11px;font-weight:600;color:var(--navy);background:var(--seafoam);border-radius:6px;padding:2px 8px;">{_esc(t)}</span>'
            for t in tags_list
        ) or '<span style="font-size:12px;color:var(--muted);">auto-tagged on enrich</span>'
        sub_badge = ('<span style="font-size:11px;font-weight:600;padding:2px 8px;border-radius:20px;'
                     'background:var(--coral-wash);color:var(--navy);margin-right:6px;">Reader suggestion</span>'
                     if (c.get("origin") or "").startswith("submission:") else "")
        meta = f"{sub_badge}{date}" if date else sub_badge
        # Approval prediction (advisory) from the suggestion engine.
        sug = suggestions.get(c["url"])
        suggest_attr = ""
        suggest_badge = ""
        if sug:
            keep = bool(sug.get("keep"))
            suggest_attr = f' data-suggest="{"keep" if keep else "skip"}"'
            reason = _esc(sug.get("reason", ""))
            if keep:
                suggest_badge = (f'<div style="font-size:12px;color:var(--seafoam-deep);margin:0 0 8px;">'
                                 f'&#10003; <strong>Likely keep</strong>{("&mdash;" + reason) if reason else ""}</div>')
            else:
                suggest_badge = (f'<div style="font-size:12px;color:var(--navy);margin:0 0 8px;">'
                                 f'&#8855; <strong>Likely skip</strong>{("&mdash;" + reason) if reason else ""}</div>')
        return f"""<div data-card data-url="{url}"{suggest_attr} style="background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin-bottom:12px;">
  <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;">
    <a href="{url}" target="_blank" rel="noopener" style="font-family:var(--font-head);font-weight:600;font-size:16px;color:var(--navy);line-height:1.35;">{title}</a>
    {_badge(c)}
  </div>
  <div style="font-size:12px;color:var(--muted);margin:3px 0 8px;">{meta}</div>
  {suggest_badge}
  <p style="font-size:14px;color:var(--ink-soft);margin:0 0 12px;line-height:1.55;">{summary}</p>
  <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px;">
    {chips}
    <button type="button" onclick="editQTags(this)" style="background:none;border:none;color:var(--muted);font-size:12px;cursor:pointer;text-decoration:underline;padding:0;">edit</button>
  </div>
  <input class="qtags" type="text" value="{tags_val}" style="display:none;width:100%;padding:8px 12px;border:1px solid var(--line);border-radius:9px;font:inherit;font-size:14px;background:var(--bg);margin-bottom:12px;">
  <div style="display:flex;gap:9px;">
    <button class="add-btn btn" onclick="addOne(this)" style="font-size:13px;padding:8px 18px;">Add to archive</button>
    <button class="btn btn-ghost" onclick="dismissOne(this)" style="font-size:13px;padding:8px 18px;">Dismiss</button>
  </div>
</div>"""

    # -- Historical sweep panel (Phase 6 merge) --------------------------------
    # Was its own page at /admin/library/backfill; now a collapsible section
    # here since it's the producer half of the same discovery -> review
    # workflow this page's own diagram describes (GET /admin/library/backfill
    # now just redirects here). Same _job_set("backfill", ...) job state, same
    # POST /admin/library/backfill/start + GET .../status routes, unchanged —
    # only the page embedding this form moved. Collapsed by default (it's a
    # rare tool, mainly right after adding a new source — see its own copy
    # below) unless a sweep is running or just finished, so there's always
    # something to see when it matters and nothing in the way when it doesn't.
    from linklib.queue import QUEUE_ENRICH_MODEL
    from linklib.models import models_for
    sweep_model_options = "".join(
        f'<option value="{m["id"]}" {"selected" if QUEUE_ENRICH_MODEL == m["id"] else ""}>'
        f'{m["label"]}—{m["blurb"]}{" (recommended)" if m["id"] == QUEUE_ENRICH_MODEL else ""}</option>'
        for m in reversed(models_for(blurb="short"))
    )
    sweep_default_since = (last_saved or "2024-06-01")[:10]
    sweep_job = _job_get("backfill")
    sweep_running = sweep_job.get("running", False)
    sweep_error = sweep_job.get("error", "")
    sweep_report = sweep_job.get("report", [])
    sweep_done = sweep_job.get("done", 0)
    sweep_total = sweep_job.get("total", 0)

    sweep_status_html = ""
    if sweep_running:
        sweep_pct = round(sweep_done / sweep_total * 100) if sweep_total else 0
        sweep_status_html = f"""
<div id="sweep-job-status" style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:10px;padding:14px 18px;margin-bottom:20px;">
  <div style="font-weight:600;font-size:14px;color:#1d4ed8;margin-bottom:4px;">Sitemap sweep in progress&hellip;</div>
  <div style="font-size:13px;color:var(--muted);">{sweep_done} / {sweep_total} sources scanned</div>
  <div style="background:#dbeafe;border-radius:6px;height:8px;margin-top:10px;overflow:hidden;">
    <div style="background:#2563eb;height:8px;width:{sweep_pct}%;transition:width .3s;"></div>
  </div>
</div>"""
    elif sweep_error:
        sweep_status_html = f'<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:10px;padding:12px 16px;margin-bottom:20px;font-size:13px;color:#b91c1c;">Error: {_esc(sweep_error)}</div>'
    elif sweep_report:
        sweep_added = sum(r.get("added", 0) for r in sweep_report)
        sweep_cands = sum(r.get("candidates", 0) for r in sweep_report)
        sweep_scope = sum(r.get("skipped_scope", 0) for r in sweep_report)
        sweep_status_html = f'<div style="background:#d1fae5;border:1px solid #6ee7b7;border-radius:10px;padding:12px 16px;margin-bottom:20px;font-size:13px;color:#065f46;">Sweep complete&mdash;{sweep_added} articles queued from {sweep_cands} candidates ({sweep_scope} skipped as off-audience)&mdash;see them in the queue below.</div>'

    def _sweep_report_row(r):
        added = r.get("added", 0)
        cands = r.get("candidates", 0)
        scope = r.get("skipped_scope", 0)
        note = r.get("note", "")
        sitemap = r.get("sitemap") or ""
        sm_link = (f'<a href="{_esc(sitemap)}" style="font-size:11px;color:var(--muted);" target="_blank">'
                   f'{_esc(sitemap[:60])}{"…" if len(sitemap) > 60 else ""}</a>'
                   if sitemap else '<span style="font-size:11px;color:var(--muted);">—</span>')
        extra = f" / {scope} off-audience" if scope else ""
        status = note if note else f'{added} added / {cands} candidates{extra}'
        status_color = "#b91c1c" if note else ("#16a34a" if added else "#92400e")
        return (f'<tr><td style="padding:8px 12px;font-size:13px;font-weight:500;">{_esc(r.get("source", ""))}</td>'
                f'<td style="padding:8px 12px;">{sm_link}</td>'
                f'<td style="padding:8px 12px;font-size:13px;color:{status_color};">{_esc(status)}</td></tr>')

    sweep_report_html = ""
    if sweep_report:
        sweep_rows_html = "".join(_sweep_report_row(r) for r in sweep_report)
        sweep_report_html = f"""
<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-bottom:8px;">
  <div style="padding:14px 18px;border-bottom:1px solid var(--line);font-weight:600;font-size:14px;">Coverage report</div>
  <div style="overflow-x:auto;">
  <table style="width:100%;border-collapse:collapse;">
    <thead><tr style="background:var(--bg);">
      <th style="padding:8px 12px;text-align:left;font-size:12px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.06em;">Source</th>
      <th style="padding:8px 12px;text-align:left;font-size:12px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.06em;">Sitemap</th>
      <th style="padding:8px 12px;text-align:left;font-size:12px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.06em;">Result</th>
    </tr></thead>
    <tbody>{sweep_rows_html}</tbody>
  </table>
  </div>
</div>"""

    sweep_disable = 'disabled style="opacity:.5;cursor:not-allowed;"' if sweep_running else ""
    sweep_open_attr = " open" if (sweep_running or sweep_error or sweep_report) else ""

    sweep_panel = f"""<details class="admin-group" style="margin-bottom:20px;background:transparent;border:1px solid var(--line);border-radius:14px;overflow:hidden;"{sweep_open_attr}>
  <summary style="list-style:none;cursor:pointer;padding:16px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;">
    <span style="display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;">
      <span style="font-size:15px;text-transform:uppercase;letter-spacing:.08em;color:var(--navy);font-weight:600;">Historical sweep</span>
      <span style="font-size:12px;color:var(--muted);">rare&mdash;mainly right after adding a new source</span>
    </span>
    <span class="disclosure-caret">&#9654;</span>
  </summary>
  <div style="padding:0 20px 20px;">
    <p style="color:var(--muted);margin:0 0 6px;font-size:13.5px;">Walks a source&rsquo;s sitemap and queues anything you haven&rsquo;t saved yet&mdash;a one-time back-catalog catch-up, typically run once right after you add a new source, not something to reach for routinely. It doesn&rsquo;t save anything by itself, it just adds to the queue below for you to review. <strong>Different from Reader content backfill</strong> (elsewhere on the Library page), which re-processes articles you&rsquo;ve <em>already</em> saved for better structure&mdash;this only ever finds articles you haven&rsquo;t saved yet.</p>
    <p style="color:var(--muted);margin:0 0 16px;font-size:13.5px;">Once a source&rsquo;s back catalog is swept, &ldquo;Scan feed&rdquo; below is what keeps you current going forward&mdash;you shouldn&rsquo;t need to run this again for that source.</p>
    {_job_run_banner("backfill")}
    <div id="sweep-poll-container">{sweep_status_html}</div>
    <div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:20px 22px;margin-bottom:20px;">
      <form id="backfill-form" method="post" action="/admin/library/backfill/start" style="display:grid;gap:18px;">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
          <div>
            <label style="display:block;font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin-bottom:6px;">Articles published since</label>
            <input type="date" name="since" value="{sweep_default_since}" max="{datetime.now().strftime('%Y-%m-%d')}"
              style="width:100%;padding:9px 12px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:14px;background:var(--bg);" required>
            <p style="font-size:12px;color:var(--muted);margin:4px 0 0;">Auto-detected from your oldest save: <strong>{sweep_default_since}</strong></p>
          </div>
          <div>
            <label style="display:block;font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin-bottom:6px;">Max articles per source</label>
            <input type="number" name="per_source" value="150" min="10" max="2000"
              style="width:100%;padding:9px 12px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:14px;background:var(--bg);">
            <p style="font-size:12px;color:var(--muted);margin:4px 0 0;">150 is a safe starting point. Raise it to reach further back&mdash;the sweep takes the most recent N, so a low cap stops early on prolific sources.</p>
          </div>
        </div>
        <div>
          <label style="display:block;font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin-bottom:6px;">Limit to sources <span style="font-weight:400;text-transform:none;letter-spacing:0;">(optional)</span></label>
          <input type="text" name="only_sources" placeholder="e.g. Kellblog, Stratechery, SaaStr"
            style="width:100%;padding:9px 12px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:14px;background:var(--bg);">
          <p style="font-size:12px;color:var(--muted);margin:4px 0 0;">Comma-separated. Leave blank to sweep everything. Re-running is safe&mdash;already-queued and saved URLs are skipped, so a bigger limit only adds the older articles you haven&rsquo;t seen yet.</p>
        </div>
        <div>
          <label style="display:block;font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin-bottom:6px;">Enrichment model</label>
          <select name="model" style="padding:9px 12px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:14px;background:var(--bg);min-width:240px;">
            {sweep_model_options}
          </select>
        </div>
        <div>
          <label style="display:flex;align-items:flex-start;gap:8px;font-size:14px;cursor:pointer;">
            <input type="checkbox" name="dry_run" value="1" checked style="margin-top:3px;accent-color:var(--accent);">
            <span><strong>Dry run</strong>
            <span style="display:block;font-size:12px;color:var(--muted);">Count candidates without fetching or enriching anything. Uncheck to do the real sweep.</span></span>
          </label>
        </div>
        <div>
          <button type="submit" class="btn" style="font-size:15px;padding:11px 28px;" {sweep_disable}>Run sweep</button>
          <span style="font-size:13px;color:var(--muted);margin-left:14px;">Runs server-side&mdash;you can leave this page.</span>
        </div>
      </form>
    </div>
    {sweep_report_html}
  </div>
</details>"""

    group_blocks = ""
    for source, cards in groups.items():
        cards_html = "".join(_card(c) for c in cards)
        s = _esc(source)
        keeps = sum(1 for c in cards if (suggestions.get(c["url"]) or {}).get("keep") is True)
        skips = sum(1 for c in cards if (suggestions.get(c["url"]) or {}).get("keep") is False)
        suggest_bar = ""
        if keeps or skips:
            kb = (f'<button class="btn btn-ghost" onclick="approveKeeps(this)" style="font-size:12px;padding:6px 14px;color:var(--seafoam-deep);">Approve {keeps} likely keep{"s" if keeps != 1 else ""}</button>' if keeps else "")
            sb = (f'<button class="btn btn-ghost" onclick="dismissSkips(this)" style="font-size:12px;padding:6px 14px;color:var(--navy);">Dismiss {skips} likely skip{"s" if skips != 1 else ""}</button>' if skips else "")
            suggest_bar = (f'<div style="display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:0 0 12px;font-size:13px;color:var(--muted);">'
                           f'<span>Predicted from your past picks:</span>{kb}{sb}</div>')
        group_blocks += f"""<details data-group class="q-group" style="margin-bottom:12px;border:1px solid var(--line);border-radius:12px;overflow:hidden;">
  <summary style="list-style:none;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 18px;">
    <span style="display:flex;align-items:center;gap:10px;min-width:0;">
      <span class="disclosure-caret">&#9654;</span>
      <h2 style="margin:0;font-size:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{s} <span class="grp-count" style="color:var(--muted);font-weight:500;font-size:14px;">({len(cards)})</span></h2>
    </span>
    <span style="display:flex;gap:9px;flex-shrink:0;">
      <form method="post" action="/admin/library/queue/suggest" style="margin:0;" onsubmit="event.stopPropagation();"><input type="hidden" name="source" value="{s}"><button type="submit" onclick="event.stopPropagation();" class="btn btn-ghost" style="font-size:12px;padding:6px 14px;">Suggest</button></form>
      <button class="btn btn-ghost" onclick="event.stopPropagation();addAll(this)" style="font-size:12px;padding:6px 14px;">Add all</button>
      <button class="btn btn-ghost" onclick="event.stopPropagation();dismissAll(this)" style="font-size:12px;padding:6px 14px;">Dismiss all</button>
    </span>
  </summary>
  <div style="padding:2px 18px 8px;">
    {suggest_bar}
    {cards_html}
  </div>
</details>"""

    pending_n = len(pending)
    if pending_n == 0:
        group_blocks = ('<div style="background:var(--surface);border:1px solid var(--line);border-radius:12px;'
                        'padding:32px;text-align:center;color:var(--muted);">Nothing waiting. Scan the feed to '
                        'find recent articles you haven&rsquo;t saved yet.</div>')

    scan_notice = ""
    if scanning:
        scan_notice = ('<div style="background:var(--seafoam-wash);border:1px solid var(--seafoam);border-radius:10px;'
                       'padding:12px 16px;margin-bottom:20px;font-size:14px;color:var(--seafoam-deep);">'
                       'Scanning the feed in the background&mdash;reload this page in a minute to see new candidates.</div>')
    elif redating:
        scan_notice = ('<div style="background:var(--seafoam-wash);border:1px solid var(--seafoam);border-radius:10px;'
                       'padding:12px 16px;margin-bottom:20px;font-size:14px;color:var(--seafoam-deep);">'
                       'Re-reading publish dates from the article pages in the background&mdash;reload in a minute to see corrected dates.</div>')
    elif suggesting:
        scan_notice = ('<div style="background:var(--seafoam-wash);border:1px solid var(--seafoam);border-radius:10px;'
                       'padding:12px 16px;margin-bottom:20px;font-size:14px;color:var(--seafoam-deep);">'
                       'Predicting which candidates you&rsquo;d keep, from your past picks&mdash;reload in a minute to see &ldquo;Likely keep / skip&rdquo; on each card.</div>')
    elif suggest_status.get("note"):
        # Show the result of the last prediction run so it's never a silent no-op.
        ok = suggest_status.get("n", 0) > 0
        bg = "var(--seafoam-wash)" if ok else "var(--coral-wash)"
        bd = "var(--seafoam)" if ok else "var(--coral)"
        col = "var(--seafoam-deep)" if ok else "var(--coral-deep)"
        scan_notice = (f'<div style="background:{bg};border:1px solid {bd};border-radius:10px;'
                       f'padding:12px 16px;margin-bottom:20px;font-size:14px;color:{col};">'
                       f'{_esc(suggest_status["note"])}</div>')

    dismissed_note = (f'<span style="color:var(--muted);font-size:13px;">{dismissed_n} dismissed</span>'
                      if dismissed_n else "")

    expand_controls = (
        '<span style="font-size:13px;color:var(--muted);">'
        '<a href="#" onclick="setAllGroups(true);return false;" style="color:var(--navy);">Expand all</a>'
        ' &middot; <a href="#" onclick="setAllGroups(false);return false;" style="color:var(--navy);">Collapse all</a>'
        '</span>' if pending_n else ''
    )

    body = f"""<div class="page page-admin">
<style>
.q-group summary:hover{{background:var(--surface);}}
</style>
<p style="margin:0 0 4px;"><a href="/admin/library" style="font-size:13px;color:var(--muted);">&larr; Library</a></p>
<h1>Archive Queue</h1>
<p style="color:var(--muted);margin:4px 0 6px;">Proposed saves waiting for your review—from &ldquo;Scan feed&rdquo; below (ongoing) or the &ldquo;Historical sweep&rdquo; panel above it (occasional, mainly right after adding a new source).</p>
<p style="color:var(--muted);margin:0 0 22px;">Approve into the archive (edit the tags first if you like), or dismiss what you don&rsquo;t want.</p>
{_content_flow_diagram(highlight="queue")}
{sweep_panel}
{scan_notice}
<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px;">
  <div><span id="pending-count" style="font-family:var(--font-head);font-weight:600;font-size:17px;color:var(--ink);">{pending_n}</span> <span style="color:var(--muted);">pending</span> &nbsp; {dismissed_note} &nbsp; {expand_controls}</div>
  <form method="post" action="/admin/library/queue/refresh-feed" style="margin:0;"><button type="submit" class="btn" style="font-size:14px;padding:9px 20px;">Scan feed</button></form>
</div>
<form method="post" action="/admin/library/queue/redate" style="margin:0 0 24px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
  <span style="font-size:13px;color:var(--muted);">Dates look wrong? Re-read them from the article pages</span>
  <input type="text" name="source" placeholder="source (blank = all)" style="padding:6px 10px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:13px;background:var(--bg);width:180px;">
  <button type="submit" class="btn btn-ghost" style="font-size:13px;padding:6px 14px;">Fix dates</button>
</form>
{group_blocks}
</div>

<script>
function cardOf(btn){{ return btn.closest('[data-card]'); }}
async function postForm(path, data){{
  try {{
    const r = await fetch(path, {{method:'POST', headers:{{'Content-Type':'application/x-www-form-urlencoded'}}, body:new URLSearchParams(data)}});
    return r.ok;
  }} catch(e) {{ return false; }}
}}
function setPending(delta){{
  const el = document.getElementById('pending-count');
  el.textContent = Math.max(0, parseInt(el.textContent || '0', 10) + delta);
}}
function removeCard(card){{
  const grp = card.closest('[data-group]');
  card.remove();
  setPending(-1);
  if (grp) {{
    const left = grp.querySelectorAll('[data-card]').length;
    const cnt = grp.querySelector('.grp-count');
    if (cnt) cnt.textContent = '(' + left + ')';
    if (left === 0) grp.remove();
  }}
}}
async function addOne(btn){{
  const card = cardOf(btn);
  const addBtn = card.querySelector('.add-btn');
  addBtn.disabled = true; addBtn.textContent = 'Adding…';
  const ok = await postForm('/admin/library/queue/add', {{url: card.dataset.url, tags: card.querySelector('.qtags').value}});
  if (ok) {{ removeCard(card); }}
  else {{ addBtn.disabled = false; addBtn.textContent = 'Add to archive'; }}
  return ok;
}}
async function dismissOne(btn){{
  const card = cardOf(btn);
  if (await postForm('/admin/library/queue/dismiss', {{url: card.dataset.url}})) removeCard(card);
}}
function setAllGroups(open){{
  document.querySelectorAll('.q-group').forEach(function(g){{ g.open = open; }});
}}
function editQTags(btn){{
  // Reveal the (otherwise hidden) tag input — tags are auto-set; editing is opt-in.
  const card = btn.closest('[data-card]');
  const input = card.querySelector('.qtags');
  btn.parentElement.style.display = 'none';
  input.style.display = 'block';
  input.focus();
}}
async function addAll(btn){{
  const grp = btn.closest('[data-group]');
  const cards = Array.from(grp.querySelectorAll('[data-card]'));
  for (const c of cards) {{ await addOne(c.querySelector('.add-btn')); }}
}}
async function approveKeeps(btn){{
  const grp = btn.closest('[data-group]');
  const cards = Array.from(grp.querySelectorAll('[data-card][data-suggest="keep"]'));
  for (const c of cards) {{ await addOne(c.querySelector('.add-btn')); }}
}}
async function dismissSkips(btn){{
  const grp = btn.closest('[data-group]');
  const cards = Array.from(grp.querySelectorAll('[data-card][data-suggest="skip"]'));
  for (const c of cards) {{ await dismissOne(c.querySelector('.add-btn')); }}
}}
async function dismissAll(btn){{
  const grp = btn.closest('[data-group]');
  const cards = Array.from(grp.querySelectorAll('[data-card]'));
  for (const c of cards) {{ await dismissOne(c.querySelector('.add-btn')); }}
}}
(function() {{
  // Historical sweep's own status poller (Phase 6 merge) — was previously on
  // its own page. Fixed a real bug while moving it: this used to fetch
  // '/admin/backfill/status' (missing the /library segment), a 404 that
  // silently never updated the UI; the real route is
  // '/admin/library/backfill/status'.
  var sweepReloadOnDone = false;
  function pollSweep() {{
    fetch('/admin/library/backfill/status').then(r => r.json()).then(function(s) {{
      var container = document.getElementById('sweep-poll-container');
      if (!container) return;
      var progPct = s.total > 0 ? Math.round(s.done / s.total * 100) : 0;
      if (s.running) {{
        sweepReloadOnDone = true;
        container.innerHTML = '<div id="sweep-job-status" style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:10px;padding:14px 18px;margin-bottom:20px;">'
          + '<div style="font-weight:600;font-size:14px;color:#1d4ed8;margin-bottom:4px;">Sitemap sweep in progress&hellip;</div>'
          + '<div style="font-size:13px;color:var(--muted);">' + s.done + ' / ' + s.total + ' sources scanned</div>'
          + '<div style="background:#dbeafe;border-radius:6px;height:8px;margin-top:10px;overflow:hidden;">'
          + '<div style="background:#2563eb;height:8px;width:' + progPct + '%;transition:width .3s;"></div></div></div>';
        setTimeout(pollSweep, 3000);
      }} else if (sweepReloadOnDone) {{
        // Job finished while we were watching — reload so the full coverage table (and the queue below) render.
        window.location.reload();
      }} else if (s.error) {{
        container.innerHTML = '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:10px;padding:12px 16px;margin-bottom:20px;font-size:13px;color:#b91c1c;">Error: ' + s.error + '</div>';
      }}
    }}).catch(function() {{ setTimeout(pollSweep, 4000); }});
  }}
  if ({str(sweep_running).lower()}) {{ sweepReloadOnDone = true; setTimeout(pollSweep, 3000); }}
  var backfillForm = document.getElementById('backfill-form');
  if (backfillForm) {{
    backfillForm.addEventListener('submit', function() {{ setTimeout(function() {{ pollSweep(); }}, 2000); }});
  }}
}})();
</script>"""
    return HTMLResponse(_page("Archive Queue—Admin", "Admin", body, authed=True))


